/* ---------- films: sparkling (ch.41), Sherry (ch.43), Port & fortified Muscats (ch.44–45), storage & service (ch.3) ---------- */
const SPFLOW=[{t:I3("pressatura, chiarifica","pressurage, débourbage","press, clarify")},{t:I3("vino base","vin de base","base wine"),io:1},{t:I3("assemblaggio","assemblage","blending")},{t:"liqueur de tirage"},{t:I3("2ª fermentazione in bottiglia","2e fermentation en bouteille","2nd fermentation in bottle")},{t:I3("sui lieviti","sur lies","on the lees")},{t:"remuage"},{t:I3("sboccatura","dégorgement","disgorge")},{t:"liqueur d'expédition"},{t:I3("metodo tradizionale","méthode traditionnelle","traditional method"),io:1}];
const SHFLOW=[{t:I3("Palomino","Palomino","Palomino"),io:1},{t:I3("vino bianco secco","vin blanc sec","dry white wine")},{t:I3("1ª classificazione","1re classification","1st classification")},{t:"15–15,5%"},{t:I3("flor: Fino, Manzanilla","flor : Fino, Manzanilla","flor: Fino, Manzanilla"),io:1},{t:I3("+ 17%: Amontillado","+ 17 % : Amontillado","+ 17%: Amontillado"),io:1},{t:"17%"},{t:I3("ossidativo: Oloroso","oxydatif : Oloroso","oxidative: Oloroso"),io:1}];
FILMS.push(
{id:"spark",sec:"s",ch:"spu",ic:"bub",t:I3("Gli spumanti: tutti i metodi","Les vins effervescents : toutes les méthodes","Sparkling wines: every method"),s:[
 {h:I3("L'uva per lo spumante","Le raisin pour l'effervescent","Grapes for sparkling wine"),
  c:I3("Le esigenze sono diverse dal vino fermo. Primo, l'uva deve avere relativamente poco zucchero: la seconda fermentazione aggiunge 1,2–1,3 gradi, quindi si punta a un vino base secco di 10–11 per cento. Secondo, serve molta acidità per uno stile rinfrescante. Terzo, nonostante zucchero basso e acidità alta, gli aromi devono essere maturi, senza note verdi ed erbacee. È facile solo nei climi più freschi, dove zuccheri, acidi e aromi cambiano lentamente e insieme; nei climi caldi lo zucchero sale e l'acidità crolla in fretta, e raccogliere presto significa spesso uve ancora verdi.",
   "Les exigences diffèrent du vin tranquille. D'abord, le raisin doit être relativement peu sucré : la seconde fermentation ajoute 1,2 à 1,3 degré, donc on vise un vin de base sec de 10 à 11 %. Ensuite, il faut beaucoup d'acidité pour un style rafraîchissant. Enfin, malgré peu de sucre et beaucoup d'acidité, les arômes doivent être mûrs, sans notes vertes et herbacées. Ce n'est facile que dans les climats les plus frais, où sucres, acides et arômes évoluent lentement et ensemble ; en climat chaud le sucre monte et l'acidité chute vite, et cueillir tôt signifie souvent un raisin encore vert.",
   "The requirements differ from still wine. First, grapes should be relatively low in sugar: the second fermentation adds 1.2–1.3% abv, so the aim is a dry base wine of 10–11%. Second, high acidity is wanted for a refreshing style. Third, despite low sugar and high acid, flavours must be ripe, with no green, herbaceous notes. This is easy only in the coolest regions, where sugar, acid and flavour change slowly and together; in warm regions sugar rises and acid falls fast, and early picking often means green, herbaceous grapes."),
  v:()=>fSvg(fGround()+fVine("ripe",-60)+fBox(190,30,120,30,w3("vino base 10–11%","vin de base 10–11 %","base wine 10–11%"))+fBox(190,70,120,30,w3("+ 1,2–1,3% in bottiglia","+ 1,2–1,3 % en bouteille","+ 1.2–1.3% in bottle"))+fBox(190,110,120,30,w3("acidità alta, aromi maturi","acidité haute, arômes mûrs","high acid, ripe flavours"),{fill:"rgba(79,168,162,.5)"}),"spring")},
 {h:I3("Raccolta e pressatura","Récolte et pressurage","Harvest and pressing"),
  c:I3("Per i migliori spumanti l'uva si raccoglie a mano, per avere grappoli interi e acini intatti; nelle zone calde, per gli spumanti economici, la macchina permette di raccogliere tutto in fretta prima che lo zucchero salga troppo. In cantina si pressa subito e con delicatezza, per estrarre poco tannino e colore, soprattutto dalle uve nere destinate a spumanti bianchi: i grappoli interi, non pigiati, riducono il contatto tra bucce e mosto. Nell'UE spesso la legge fissa la pressione massima e la quantità di mosto ricavabile.",
   "Pour les meilleurs effervescents, le raisin est cueilli à la main, pour garder des grappes entières et des baies intactes ; dans les zones chaudes, pour les effervescents bon marché, la machine permet de tout récolter vite avant que le sucre ne monte trop. Au chai on presse aussitôt et en douceur, pour extraire peu de tanins et de couleur, surtout des raisins noirs destinés à des effervescents blancs : les grappes entières, non foulées, réduisent le contact peaux-jus. Dans l'UE la loi fixe souvent la pression maximale et la quantité de jus extraite.",
   "For the best sparkling wines grapes are hand-picked to keep whole bunches of unsplit berries; in warm regions, for inexpensive styles, machines can pick everything quickly before sugar climbs too high. At the winery grapes are pressed at once and gently, to extract little tannin or colour, especially from black grapes used for white sparkling wine: whole, uncrushed bunches minimise skin contact. In most EU regions the law sets the maximum pressure and the amount of juice that can be extracted."),
  v:()=>fSvg(fBasketPress(100,150,WHITE)+fCrate(220,170)+`<g>${fBunch(220,110,1.2,"#3d1a3a")}<animateTransform attributeName="transform" type="translate" values="0 0;-110 0;-110 0" dur="3s" repeatCount="indefinite"/></g>`+fChip(220,40,w3("grappoli interi, pressatura dolce","grappes entières, pressurage doux","whole bunches, gentle pressing")))},
 {h:I3("I cinque metodi","Les cinq méthodes","The five methods"),
  c:I3("Lo spumante si fa con uno di cinque metodi: tradizionale, transfer, in autoclave o Charmat, metodo Asti e gassificazione. In Europa la scelta può essere imposta dalla legge locale; altrove dipende dallo stile, dalla qualità voluta e dai costi. Il metodo tradizionale, con seconda fermentazione nella bottiglia in cui il vino viene venduto, è il più usato per gli spumanti di alta gamma: costoso e lungo, ma dà i vini più pregiati.",
   "L'effervescent se fait selon l'une de cinq méthodes : traditionnelle, transfert, cuve close ou Charmat, méthode Asti et gazéification. En Europe le choix peut être imposé par la loi locale ; ailleurs il dépend du style, de la qualité voulue et des coûts. La méthode traditionnelle, avec seconde fermentation dans la bouteille où le vin est vendu, est la plus utilisée pour les effervescents haut de gamme : coûteuse et longue, mais elle donne les vins les plus prisés.",
   "Sparkling wine is made by one of five methods: traditional, transfer, tank (Charmat), Asti method and carbonation. In Europe the choice may be set by local law; elsewhere it depends on style, quality and cost. The traditional method, with a second fermentation in the bottle in which the wine is sold, is the most common for premium sparkling wine: costly and slow, but it makes the most prized wines."),
  v:()=>fSvg([[I3("tradizionale","traditionnelle","traditional"),"#8c1d40"],["transfer","#6b2d5c"],[I3("autoclave","cuve close","tank"),"#1f6f6b"],["Asti","#a87b1e"],[I3("gassificazione","gazéification","carbonation"),"#5c646b"]].map(([l,c],i)=>fD(i*.35,fBox(10+i*61,70,56,50,tx(l),{fill:c,sz:8}))).join("")+fT(160,150,w3("dal più pregiato al più economico","du plus prisé au moins cher","most prestigious → cheapest"),9.5)+fArrow("M30 164H290",null,1))},
 {h:I3("Metodo tradizionale: il vino base","Méthode traditionnelle : le vin de base","Traditional method: the base wine"),
  c:I3("La prima fermentazione avviene di solito in grandi vasche d'acciaio a temperatura controllata, ma alcuni usano ancora botti o barrique per una parte dei vini. Il vino base è completamente secco, neutro e molto acido. Il produttore decide, secondo lo stile, se fargli fare la malolattica e un periodo in rovere prima della seconda fermentazione. Quasi tutti i vini base si usano l'anno dopo la vendemmia, ma alcuni si conservano per gli anni seguenti: sono i vini di riserva, importantissimi nell'assemblaggio.",
   "La première fermentation a lieu en général dans de grandes cuves inox thermorégulées, mais certains utilisent encore des foudres ou barriques pour une partie des vins. Le vin de base est complètement sec, neutre et très acide. Le producteur décide, selon le style, s'il fera la malolactique et un passage en chêne avant la seconde fermentation. La plupart des vins de base servent l'année suivant la vendange, mais certains sont gardés pour les années suivantes : ce sont les vins de réserve, essentiels dans l'assemblage.",
   "The first fermentation usually takes place in large temperature-controlled stainless steel vats, though some producers still use oak vats or barrels for part of their wines. The base wine is fully dry, neutral and high in acid. Depending on style, the winemaker decides whether it undergoes MLF and/or oak maturation before the second fermentation. Most base wines are used the year after harvest, but some are kept for future years: these reserve wines are vital in blending."),
  v:()=>fSvg(STEEL(20,50,70,110,{col:WHITE,lv:.75,cold:1})+STEEL(100,50,70,110,{col:WHITE,lv:.75,cold:1})+fBarrel(225,110,1)+fD(1.2,fBox(190,30,110,30,w3("vini di riserva","vins de réserve","reserve wines"),{fill:"rgba(212,162,58,.5)"}))+fChip(95,186,w3("secco, neutro, acido","sec, neutre, acide","dry, neutral, high acid")))},
 {h:I3("L'assemblaggio","L'assemblage","Blending"),
  c:I3("È fondamentale per gli spumanti, con tre funzioni. Stile della casa: assemblando vigneti, varietà e annate diverse si mantiene lo stesso stile ogni anno, soprattutto per i non millesimati. Equilibrio: lo Chardonnay porta agrumi, finezza e longevità, il Pinot Noir frutti rossi e corpo. Complessità: i vecchi vini di riserva danno note di frutta secca alla freschezza dei giovani, e i vini passati in legno più ampiezza e spezie. Più vini si hanno a disposizione, più è facile: per questo l'uva si vinifica in tante piccole partite separate.",
   "Il est essentiel pour les effervescents, avec trois fonctions. Style maison : en assemblant parcelles, cépages et années, on garde le même style chaque année, surtout pour les non millésimés. Équilibre : le Chardonnay apporte agrumes, finesse et longévité, le Pinot Noir fruits rouges et corps. Complexité : les vieux vins de réserve donnent des notes de fruits secs à la fraîcheur des jeunes, et les vins élevés en bois plus d'ampleur et d'épices. Plus on dispose de vins, plus c'est facile : c'est pourquoi on vinifie en nombreux petits lots séparés.",
   "Blending is vital for sparkling wine and has three functions. House style: blending vineyards, varieties and vintages keeps the same style every year, especially for non-vintage wines. Balance: Chardonnay brings citrus, finesse and longevity, Pinot Noir red fruit and body. Complexity: old reserve wines add dried-fruit notes to the freshness of young wine, and oak-aged wines add breadth and spice. The more wines available, the easier it is, which is why grapes are fermented in many small separate parcels."),
  v:()=>fSvg(fBox(14,30,90,40,"Chardonnay: "+w3("agrumi, finezza","agrumes, finesse","citrus, finesse"),{fill:"rgba(233,220,140,.35)"})+fBox(114,30,90,40,"Pinot Noir: "+w3("frutti rossi, corpo","fruits rouges, corps","red fruit, body"),{fill:"rgba(140,29,64,.5)"})+fBox(214,30,90,40,w3("riserve: frutta secca","réserves : fruits secs","reserves: dried fruit"),{fill:"rgba(212,162,58,.4)"})+[60,160,260].map(x=>fArrow(`M${x} 74Q${x} 110 160 120`,null,1)).join("")+STEEL(120,120,80,64,{col:WHITE,lv:.7})+fChip(260,170,w3("stile della casa","style maison","house style")))},
 {h:I3("Il tiraggio","Le tirage","Tirage"),
  c:I3("Fatto l'assemblaggio, si aggiunge una piccola quantità di liqueur de tirage: vino, zucchero, lieviti, nutrienti per i lieviti e un coadiuvante per la chiarifica. La bottiglia si chiude con un tappo a corona che contiene un piccolo bicchierino di plastica. Le bottiglie si accatastano coricate nelle cantine del produttore, a temperatura fresca e costante.",
   "L'assemblage terminé, on ajoute une petite quantité de liqueur de tirage : vin, sucre, levures, nutriments pour les levures et un adjuvant de clarification. La bouteille est fermée par une capsule contenant un petit godet en plastique, le bidule. Les bouteilles sont empilées couchées dans les caves du producteur, à température fraîche et constante.",
   "Once the blend is made, a small amount of liqueur de tirage is added: wine, sugar, yeast, yeast nutrients and a clarifying agent. The bottle is sealed with a crown cap containing a small plastic cup insert. The bottles are stacked horizontally in the producer's cellars at a cool, constant temperature."),
  v:()=>fSvg(fBottle(120,120,{col:WHITE})+`<g><path d="M80 20h20l-4 20h-12z" fill="#fbf3e2"/><animateTransform attributeName="transform" type="rotate" values="0 90 30;35 90 30;35 90 30;0 90 30" dur="3s" repeatCount="indefinite"/></g>`+fDrops(116,50,80,"#fbf3e2",3)+fD(2,`<rect x="115" y="76" width="10" height="5" rx="1" fill="#c9ced3"/>`)+fD(.5,fBox(180,30,130,60,w3("vino + zucchero + lieviti + nutrienti + chiarificante","vin + sucre + levures + nutriments + adjuvant","wine + sugar + yeast + nutrients + clarifier")))+fD(2.6,[0,1,2].map(i=>`<g transform="translate(${190+i*44} 150) rotate(90)">${fBottle(0,0,{col:WHITE,crown:1})}</g>`).join("")))},
 {h:I3("La seconda fermentazione","La prise de mousse","The second fermentation"),
  c:I3("In bottiglia avviene una fermentazione lenta. L'alcol sale di circa 1,2–1,3 gradi e l'anidride carbonica prodotta dai lieviti, non potendo uscire, si scioglie nel vino creando le bollicine. La pressione nella bottiglia arriva a cinque–sei atmosfere.",
   "En bouteille a lieu une fermentation lente. L'alcool augmente d'environ 1,2 à 1,3 degré et le gaz carbonique produit par les levures, ne pouvant s'échapper, se dissout dans le vin et crée les bulles. La pression dans la bouteille atteint cinq à six atmosphères.",
   "A slow fermentation takes place in the bottle. Alcohol rises by about 1.2–1.3% abv and the carbon dioxide made by the yeast, unable to escape, dissolves into the wine to create the sparkle. Pressure in the bottle reaches five to six atmospheres."),
  v:()=>fSvg(fBottle(110,110,{col:WHITE,crown:1,bub:1,lees:1})+fGauge(230,90,95,"5–6 atm")+fChip(110,180,"+1,2–1,3% vol"))},
 {h:I3("L'autolisi","L'autolyse","Yeast autolysis"),
  c:I3("Finita la seconda fermentazione, i lieviti muoiono e formano un deposito di fecce nella bottiglia. Nel giro di mesi le cellule morte iniziano a decomporsi e liberano composti nel vino: è l'autolisi, che dà note di pane, biscotto e tostato. Di solito dura quattro–cinque anni, ma può continuare fino a dieci; più il vino resta sulle fecce, più il carattere di lievito è marcato. Anche dopo, il contatto con le fecce mantiene il vino fresco per anni.",
   "La prise de mousse terminée, les levures meurent et forment un dépôt de lies dans la bouteille. En quelques mois, les cellules mortes commencent à se décomposer et libèrent des composés dans le vin : c'est l'autolyse, qui donne des notes de pain, biscuit et toasté. Elle dure en général quatre à cinq ans, mais peut se poursuivre jusqu'à dix ; plus le vin reste sur lies, plus le caractère levuré est marqué. Même ensuite, le contact avec les lies garde le vin frais pendant des années.",
   "When the second fermentation finishes, the yeast die and form a sediment of lees in the bottle. Over months the dead cells start to break down and release compounds into the wine: this is yeast autolysis, giving bread, biscuit and toast notes. It usually lasts four to five years but can continue for up to ten; the longer on the lees, the more pronounced the yeasty character. Even afterwards, lees contact keeps the wine fresh for years."),
  v:()=>fSvg([0,1,2,3,4,5].map(i=>`<g transform="translate(${70+(i%3)*90} ${110+Math.floor(i/3)*34}) rotate(90)">${fBottle(0,0,{col:WHITE,crown:1,lees:1})}</g>`).join("")+fClock(60,46,w3("mesi → anni","mois → années","months → years"))+fD(1.4,fChip(200,46,w3("pane · biscotto · tostato","pain · biscuit · toasté","bread · biscuit · toast"),"#d4a23a","#2a1b20")))},
 {h:I3("Il remuage","Le remuage","Riddling"),
  c:I3("Il deposito si toglie con due operazioni: remuage e sboccatura. Il remuage porta lentamente la bottiglia da orizzontale a capovolta: il deposito si stacca e scivola lungo il vetro fino al bicchierino nel tappo. Un tempo si faceva a mano sulle pupitres, cavalletti a forma di A: ogni giorno si dava a ogni bottiglia una scossa, una rotazione e un po' più di inclinazione, fino a otto settimane. Oggi si usano le gyropalette, gabbie da 500 bottiglie su un braccio idraulico che ruotano e si inclinano: il lavoro si fa in pochi giorni.",
   "Le dépôt se retire en deux opérations : remuage et dégorgement. Le remuage amène lentement la bouteille de l'horizontale à la verticale tête en bas : le dépôt se détache et glisse le long du verre jusqu'au godet de la capsule. Autrefois on le faisait à la main sur des pupitres en forme de A : chaque jour on donnait à chaque bouteille une secousse, une rotation et un peu plus d'inclinaison, jusqu'à huit semaines. Aujourd'hui on utilise des gyropalettes, des cages de 500 bouteilles sur un bras hydraulique qui tournent et s'inclinent : le travail se fait en quelques jours.",
   "The sediment is removed in two steps: riddling and disgorgement. Riddling slowly moves the bottle from horizontal to upside down: the sediment loosens and slides down the glass into the cup in the crown cap. It was once done by hand on A-frame racks called pupitres: each day every bottle got a shake, a twist and a little more tilt, taking up to eight weeks. Today gyropalettes are used, cages of 500 bottles on a hydraulic arm that rotate and tilt: the job takes a few days."),
  v:()=>fSvg(`<path d="M30 180L80 50L130 180" stroke="#8a5a33" stroke-width="9" fill="none"/>`+[0,1,2].map(i=>fBottle(84+i*14,80+i*30,{col:WHITE,crown:1,rot:100,rotTo:170,rd:3.5,rb:.3+i*.2})).join("")+fT(80,196,w3("pupitre: 8 settimane","pupitre : 8 semaines","pupitre: 8 weeks"),9)+fGyro(240,170)+fT(240,196,w3("gyropalette: giorni","gyropalette : jours","gyropalette: days"),9))},
 {h:I3("La sboccatura","Le dégorgement","Disgorgement"),
  c:I3("Finito il remuage, il collo della bottiglia capovolta si immerge in una soluzione salina gelida che congela il vino nel collo. La bottiglia si raddrizza e il ghiacciolo tiene fermo il deposito. Si toglie il tappo a corona e la pressione dell'anidride carbonica espelle il ghiacciolo con il deposito e il bicchierino. Oggi tutto è meccanizzato e dall'apertura alla nuova chiusura passano pochi secondi: si evita di perdere pressione e si riduce il rischio di ossidazione.",
   "Le remuage terminé, le col de la bouteille renversée est plongé dans une saumure glacée qui gèle le vin du col. On redresse la bouteille et le glaçon retient le dépôt. On retire la capsule et la pression du gaz carbonique expulse le glaçon avec le dépôt et le godet. Aujourd'hui tout est mécanisé et de l'ouverture au rebouchage il ne s'écoule que quelques secondes : on évite de perdre la pression et on limite le risque d'oxydation.",
   "After riddling, the neck of the inverted bottle is dipped in a very cold brine that freezes the wine in the neck. The bottle is turned upright and the frozen plug holds the sediment in place. The crown cap is removed and the pressure of the dissolved CO₂ shoots out the ice with the sediment and plastic cup. Today it is fully mechanised and only seconds pass from opening to resealing, avoiding loss of pressure and reducing oxidation risk."),
  v:()=>fSvg(`<rect x="40" y="150" width="110" height="40" rx="6" fill="#9fd3f0" opacity=".8"/>`+fBottle(95,106,{col:WHITE,rot:180,neckLees:1})+fArrow("M160 110H190")+fBottle(240,130,{col:WHITE})+`<g><animateTransform attributeName="transform" type="translate" values="0 0;0 0;30 -90" keyTimes="0;.5;1" dur="2.6s" repeatCount="indefinite"/><rect x="235" y="78" width="10" height="10" rx="2" fill="#e6f4fb" stroke="#9fd3f0"/><rect x="236" y="81" width="8" height="5" fill="#d8c79a"/></g>`)},
 {h:I3("Il dosaggio","Le dosage","Dosage"),
  c:I3("Il vino perso si rimpiazza con la liqueur d'expédition, vino e zucchero: la quantità di zucchero, il dosaggio, decide la dolcezza finale, bilancia l'acidità e aiuta l'evoluzione aromatica. Anche il vino della liqueur conta, fresco, passato in legno o invecchiato in bottiglia: è un secondo assemblaggio. Le menzioni UE: Brut Nature o dosaggio zero da 0 a 3 grammi per litro, senza zucchero aggiunto; Extra Brut da 0 a 6; Brut da 0 a 12; Extra Dry da 12 a 17; Sec da 17 a 32; Demi-Sec da 32 a 50; Doux oltre 50. Per l'esame bastano Brut Nature, Brut e Demi-Sec.",
   "On remplace le vin perdu par la liqueur d'expédition, vin et sucre : la quantité de sucre, le dosage, détermine la douceur finale, équilibre l'acidité et aide l'évolution aromatique. Le vin de la liqueur compte aussi, frais, élevé en bois ou vieilli en bouteille : c'est un second assemblage. Les mentions UE : Brut Nature ou dosage zéro de 0 à 3 grammes par litre, sans sucre ajouté ; Extra Brut de 0 à 6 ; Brut de 0 à 12 ; Extra Dry de 12 à 17 ; Sec de 17 à 32 ; Demi-Sec de 32 à 50 ; Doux plus de 50. Pour l'examen, Brut Nature, Brut et Demi-Sec suffisent.",
   "The lost wine is replaced with liqueur d'expédition, wine and sugar: the amount of sugar, the dosage, sets the final sweetness, balances the acidity and helps flavour development. The wine in the liqueur matters too, fresh, oak-aged or bottle-aged: it is a second blending. EU terms: Brut Nature or zero dosage, 0–3 grams per litre, with no sugar added; Extra Brut 0–6; Brut 0–12; Extra Dry 12–17; Sec 17–32; Demi-Sec 32–50; Doux over 50. For the exam you only need Brut Nature, Brut and Demi-Sec."),
  v:()=>fSvg(fTable([I3("Menzione","Mention","Term"),"g/l"],[["Brut Nature / 0","0–3"],["Extra Brut","0–6"],["Brut","0–12"],["Extra Dry","12–17"],["Sec","17–32"],["Demi-Sec","32–50"],["Doux","50+"]],[0,2,5],{y:10,rh:25}))},
 {h:I3("Tappatura e affinamento in bottiglia","Bouchage et vieillissement en bouteille","Corking and bottle ageing"),
  c:I3("Quasi tutti gli spumanti si chiudono con un tappo di sughero, che in origine è un cilindro con una base circa tre volte più larga dell'imboccatura: va compresso molto per entrare, e la forma a fungo nasce dopo. Una gabbietta di filo metallico lo tiene fermo. Il vino può poi riposare qualche mese perché la liqueur si integri; quasi tutti sono pronti alla vendita, ma alcuni grandi spumanti migliorano ancora. Poiché pochi sono millesimati, alcuni produttori indicano in etichetta la data di sboccatura.",
   "Presque tous les effervescents sont fermés par un bouchon de liège, qui est à l'origine un cylindre d'une section environ trois fois plus large que le goulot : il doit être fortement comprimé pour entrer, et la forme de champignon apparaît ensuite. Un muselet de fil métallique le maintient. Le vin peut ensuite reposer quelques mois pour que la liqueur s'intègre ; presque tous sont prêts à la vente, mais certains grands effervescents s'améliorent encore. Comme peu sont millésimés, certains producteurs indiquent la date de dégorgement sur l'étiquette.",
   "Almost all sparkling wines are sealed with a cork, which starts as a cylinder whose face is about three times the area of the bottle opening: it must be heavily compressed to go in, and the mushroom shape forms afterwards. A wire cage holds it secure. The wine may then rest a few months for the liqueur to integrate; most are ready to drink on release, but some premium wines improve further. As few are vintage-dated, some producers print the disgorgement date on the label."),
  v:()=>fSvg(`<g transform="translate(80 110)"><rect x="-14" y="-40" width="28" height="44" rx="4" fill="#d4a46a"/></g>`+fArrow("M110 100H150")+fBottle(200,130,{col:WHITE,cork:1,label:1})+fClosure("spark",270,110)+fChip(200,24,w3("tappo compresso + gabbietta","bouchon comprimé + muselet","compressed cork + wire cage"))+fD(1.5,fChip(270,160,w3("data di sboccatura","date de dégorgement","disgorgement date"))))},
 {h:I3("Il metodo transfer","La méthode transfert","The transfer method"),
  c:I3("È una variante del metodo tradizionale che evita remuage e sboccatura, costosi e complessi. Fino alla fine dell'affinamento sui lieviti tutto è identico; poi il contenuto delle bottiglie si svuota in una vasca pressurizzata, si filtra per togliere le fecce, si aggiunge la liqueur d'expédition e si imbottiglia in bottiglie nuove. Dà buoni spumanti a prezzi più bassi e qualità costante su grandi lotti. In etichetta si legge spesso «fermentato in bottiglia», mentre chi usa il metodo tradizionale scrive volentieri «metodo tradizionale».",
   "C'est une variante de la méthode traditionnelle qui évite remuage et dégorgement, coûteux et complexes. Jusqu'à la fin du séjour sur lies tout est identique ; puis le contenu des bouteilles est vidé dans une cuve sous pression, filtré pour retirer les lies, additionné de liqueur d'expédition et remis dans des bouteilles neuves. Elle donne de bons effervescents moins chers et une qualité régulière sur de gros lots. L'étiquette indique souvent « fermenté en bouteille », alors que les adeptes de la méthode traditionnelle écrivent volontiers « méthode traditionnelle ».",
   "A variation of the traditional method that avoids the costly, complex riddling and disgorgement. Everything is the same until the end of lees ageing; then the bottles are emptied into a pressurised tank, the wine is filtered to remove the lees, liqueur d'expédition is added and it is rebottled into fresh bottles. It gives good sparkling wine more cheaply, with consistent quality in large batches. Labels often say 'bottle-fermented', while traditional-method producers proudly state 'traditional method'."),
  v:()=>fSvg([0,1,2].map(i=>fBottle(40+i*30,110,{col:WHITE,crown:1,lees:1,rot:150})).join("")+fArrow("M120 110H150",null,1)+STEEL(150,50,80,110,{col:WHITE,lv:.75})+fGauge(190,40,95,"")+fArrow("M236 110H256",null,1)+fBottle(286,120,{col:WHITE,cork:1,label:1})+fChip(286,186,w3("«fermentato in bottiglia»","« fermenté en bouteille »","'bottle-fermented'")))},
 {h:I3("Il metodo in autoclave","La méthode en cuve close","The tank method"),
  c:I3("A differenza dei metodi in bottiglia, conserva gli aromi del vino base: ideale per varietà aromatiche come Moscato e Riesling e per spumanti fruttati come il Prosecco. È più economico, veloce e meno laborioso. La prima fermentazione avviene in acciaio a temperatura controllata, di solito senza malolattica né legno. Si aggiungono lieviti, zucchero, nutrienti e chiarificanti e la seconda fermentazione avviene in una vasca sigillata che regge la pressione. Il vino si filtra e si imbottiglia sotto pressione. Di solito non ha note di autolisi; si potrebbero ottenere rimescolando le fecce con delle pale, ma quasi tutti preferiscono il frutto primario.",
   "Contrairement aux méthodes en bouteille, elle conserve les arômes du vin de base : idéale pour les cépages aromatiques comme le Muscat et le Riesling et pour les effervescents fruités comme le Prosecco. Elle est moins chère, plus rapide et moins laborieuse. La première fermentation a lieu en inox thermorégulé, en général sans malolactique ni bois. On ajoute levures, sucre, nutriments et adjuvants, et la seconde fermentation se déroule dans une cuve close résistant à la pression. Le vin est filtré et mis en bouteille sous pression. Il n'a généralement pas de notes d'autolyse ; on pourrait en obtenir en remuant les lies avec des pales, mais presque tous préfèrent le fruit primaire.",
   "Unlike bottle-fermented methods, it keeps the flavours of the base wine: ideal for aromatic varieties such as Muscat and Riesling and fruity styles like Prosecco. It is cheaper, faster and less labour-intensive. The first fermentation is in temperature-controlled steel, usually without MLF or oak. Yeast, sugar, nutrients and clarifying agents are added and the second fermentation takes place in a sealed tank that withstands the pressure. The wine is filtered and bottled under pressure. It usually shows no autolytic notes; these could be created by stirring the lees with paddles, but most producers prefer primary fruit."),
  v:()=>fSvg(STEEL(40,30,120,140,{col:WHITE,lv:.75,bub:18})+fGauge(100,22,95,"")+`<path d="M160 130H300" stroke="#6c757d" stroke-width="6"/>`+[0,1,2].map(i=>`<g>${fBottle(190+i*40,94,{col:WHITE,cork:1})}<animateTransform attributeName="transform" type="translate" from="-30 0" to="30 0" dur="3s" repeatCount="indefinite"/></g>`).join("")+fChip(240,40,"Prosecco · Moscato · Riesling","#d4a23a","#2a1b20"))},
 {h:I3("Il metodo Asti","La méthode Asti","The Asti method"),
  c:I3("Si usa soprattutto per gli spumanti dolci di Asti, in Piemonte, ed è particolare perché c'è una sola fermentazione. Il mosto si conserva refrigerato finché serve; poi si scalda e fermenta in vasche pressurizzate. All'inizio l'anidride carbonica si lascia uscire; a metà fermentazione la vasca si chiude e il gas resta nel vino. Si arriva a circa il 7 per cento di alcol e a cinque–sei atmosfere; allora si ferma la fermentazione raffreddando, si filtra sotto pressione per togliere i lieviti e si imbottiglia per la vendita immediata.",
   "On l'utilise surtout pour les effervescents doux d'Asti, au Piémont, et elle est particulière car il n'y a qu'une seule fermentation. Le moût est conservé au froid jusqu'à son utilisation ; puis il est réchauffé et fermente en cuves pressurisées. Au début on laisse s'échapper le gaz carbonique ; à mi-fermentation la cuve est fermée et le gaz reste dans le vin. On atteint environ 7 % d'alcool et cinq à six atmosphères ; on arrête alors la fermentation par le froid, on filtre sous pression pour retirer les levures et on met en bouteille pour la vente immédiate.",
   "Used mainly for the sweet sparkling wines of Asti in Piemonte, it is unusual because there is only one fermentation. The juice is chilled and stored until needed; then it is warmed and ferments in pressurised tanks. At first the CO₂ is allowed to escape; part-way through, the tank is sealed so the gas is retained. Fermentation continues to about 7% abv and five to six atmospheres; it is then stopped by chilling, the wine is filtered under pressure to remove the yeast and bottled for immediate sale."),
  v:()=>fSvg(STEEL(70,30,120,140,{col:"#efe3a0",lv:.75,bub:12,cold:1})+`<g><path d="M130 30V10" stroke="#5c646b" stroke-width="4"/><circle cx="130" cy="8" r="5" fill="#d4a23a"><animate attributeName="fill" values="#86b85a;#86b85a;#b5334a;#b5334a" keyTimes="0;.45;.5;1" dur="5s" repeatCount="indefinite"/></circle></g>`+fThermo(230,56,"",.15,"#4fa8a2")+fChip(250,150,"≈ 7% · 5–6 atm","#d4a23a","#2a1b20")+fChip(60,190,w3("una sola fermentazione","une seule fermentation","single fermentation")))},
 {h:I3("La gassificazione","La gazéification","Carbonation"),
  c:I3("Si inietta anidride carbonica in un vino fermo, poi lo si imbottiglia sotto pressione. Conserva gli aromi del vino base, per questo si usa per spumanti da varietà molto aromatiche come il Sauvignon Blanc. È il metodo più economico di tutti.",
   "On injecte du gaz carbonique dans un vin tranquille, puis on le met en bouteille sous pression. Il conserve les arômes du vin de base, c'est pourquoi on l'utilise pour des effervescents de cépages très aromatiques comme le Sauvignon Blanc. C'est la méthode la moins chère de toutes.",
   "Carbon dioxide is injected into a still wine, which is then bottled under pressure. It keeps the base wine's flavours, so it is used for sparkling wines from strongly flavoured varieties such as Sauvignon Blanc. It is the cheapest method of all."),
  v:()=>fSvg(STEEL(110,40,100,130,{col:WHITE,lv:.75,bub:20})+`<rect x="40" y="60" width="30" height="90" rx="10" fill="#5c646b"/>`+fT(55,110,"CO₂",10)+`<path d="M70 100H110" stroke="#9fd3f0" stroke-width="4" stroke-dasharray="6 4"><animate attributeName="stroke-dashoffset" from="20" to="0" dur=".6s" repeatCount="indefinite"/></path>`+fChip(260,90,w3("il più economico","le moins cher","cheapest"),"#5c646b"))},
 {h:I3("Gli stili di spumante","Les styles d'effervescents","Styles of sparkling wine"),
  c:I3("Non millesimato: non è una menzione legale, ma indica vini da più annate, il prodotto standard che esprime lo stile della casa. Millesimato: in Champagne viene da un solo anno; altrove a volte si ammette una piccola parte di altre annate. In Champagne si fa solo nelle annate migliori, ed è più caro. Rosé: assemblando vino base rosso e bianco o con una breve macerazione; il colore si può correggere con la liqueur, e alcune denominazioni ammettono solo la macerazione. Blanc de Blancs: solo uve bianche. Blanc de Noirs: spumante bianco da sole uve nere. Prestige Cuvée: non è una menzione legale, ma indica i migliori vini di una casa.",
   "Non millésimé : ce n'est pas une mention légale, mais il désigne des vins de plusieurs années, le produit standard qui exprime le style maison. Millésimé : en Champagne il provient d'une seule année ; ailleurs on admet parfois une petite part d'autres années. En Champagne il ne se fait que dans les meilleures années, et il est plus cher. Rosé : par assemblage de vins de base rouge et blanc ou par une courte macération ; la couleur peut se corriger avec la liqueur, et certaines appellations n'admettent que la macération. Blanc de Blancs : uniquement des raisins blancs. Blanc de Noirs : effervescent blanc issu uniquement de raisins noirs. Cuvée de prestige : pas une mention légale, mais les meilleurs vins d'une maison.",
   "Non-vintage: not a labelling term, but it describes wines from more than one year, the producer's standard wine expressing the house style. Vintage: in Champagne from a single year; elsewhere a small share of other years may be allowed. In Champagne vintage wines are made only in the best years and cost more. Rosé: by blending red and white base wines or by short maceration; colour can be adjusted with the liqueur, and some appellations allow only maceration. Blanc de Blancs: white grapes only. Blanc de Noirs: white sparkling wine from black grapes only. Prestige Cuvée: not a labelling term, but a producer's best wines."),
  v:()=>fSvg([["NV","#e9dc8c"],[w3("millesimato","millésimé","vintage"),"#e3c76a"],["rosé","#f0a3a0"],["Blanc de Blancs","#f3ecb0"],["Blanc de Noirs","#efd9a0"],["Prestige","#d4a23a"]].map(([l,c],i)=>fD(i*.3,fFlute(36+i*50,120,c,1.1)+fT(36+i*50,i%2?182:168,l,8))).join(""))}
]},
{id:"sherry",sec:"s",ch:"she",ic:"order",t:I3("Lo Sherry, passo per passo","Le Xérès, étape par étape","Sherry, step by step"),s:[
 {h:I3("Dove nasce lo Sherry","Où naît le Xérès","Where Sherry is made"),
  c:I3("Lo Sherry è definito soprattutto dai processi di affinamento: sistema solera, invecchiamento biologico e ossidativo. Il vigneto circonda Jerez de la Frontera, nel sud della Spagna. Il vino deve maturare in città o in una delle due cittadine sul mare, Sanlúcar de Barrameda ed El Puerto de Santa María.",
   "Le Xérès se définit surtout par ses procédés d'élevage : système de solera, vieillissement biologique et oxydatif. Le vignoble entoure Jerez de la Frontera, dans le sud de l'Espagne. Le vin doit s'élever en ville ou dans l'une des deux petites villes côtières, Sanlúcar de Barrameda et El Puerto de Santa María.",
   "Sherry is defined above all by its maturation processes: the solera system, biological and oxidative ageing. The vineyards surround Jerez de la Frontera in southern Spain. The wine must be matured in the city or in one of the two seaside towns, Sanlúcar de Barrameda and El Puerto de Santa María."),
  v:()=>fSvg(fSea(0,0,90,200)+`<path d="M90 0H320V200H90Z" fill="#e8dcb8"/>`+[[120,60,"Sanlúcar de Barrameda"],[130,150,"El Puerto de Santa María"],[220,100,"Jerez de la Frontera"]].map(([x,y,l],i)=>fD(i*.4,`<circle cx="${x}" cy="${y}" r="6" fill="#8c1d40"/>`+fT(x+(i===2?0:10),y-10,l,9,"#3a2a2f",i===2?"middle":"start"))).join("")+fD(1.4,`<path d="M120 60L220 100L130 150Z" fill="rgba(140,29,64,.15)" stroke="#8c1d40" stroke-dasharray="4 3"/>`))},
 {h:I3("Clima e venti","Climat et vents","Climate and winds"),
  c:I3("Jerez ha un clima mediterraneo caldo e soleggiato. I vigneti vicini alla costa sono un po' più freschi e godono del poniente, vento fresco e umido da ovest. A volte il levante, caldo e secco da est, fa salire le temperature e può stressare le viti e danneggiare l'uva. Essendo sulla costa, la pioggia annua è alta per la Spagna, ma ne cade poca durante la stagione vegetativa.",
   "Jerez a un climat méditerranéen chaud et ensoleillé. Les vignes proches de la côte sont un peu plus fraîches et profitent du poniente, vent frais et humide d'ouest. Parfois le levante, chaud et sec venu de l'est, fait grimper les températures et peut stresser les vignes et abîmer le raisin. Région côtière, les pluies annuelles sont élevées pour l'Espagne, mais il en tombe peu pendant la saison de croissance.",
   "Jerez has a hot, sunny Mediterranean climate. Vineyards nearer the coast are a little cooler and benefit from the poniente, a cool, humid westerly wind. At times the levante, a hot, drying easterly, sends temperatures soaring and can stress the vines and damage the grapes. Being coastal, annual rainfall is high for Spain, but little falls during the growing season."),
  v:()=>fSvg(fSun(160,36,16)+`<path d="M0 200V140Q160 130 320 140V200Z" fill="#e8dcb8"/>`+fRows(40,180,280,180,0)+[0,1,2].map(i=>`<path d="M${10} ${80+i*14}h50" stroke="#9fd3f0" stroke-width="3" stroke-linecap="round"><animateTransform attributeName="transform" type="translate" from="0 0" to="120 0" dur="2s" begin="${i*.3}s" repeatCount="indefinite"/></path>`).join("")+[0,1,2].map(i=>`<path d="M${310} ${80+i*14}h-50" stroke="#e2622a" stroke-width="3" stroke-linecap="round"><animateTransform attributeName="transform" type="translate" from="0 0" to="-120 0" dur="2s" begin="${i*.3}s" repeatCount="indefinite"/></path>`).join("")+fChip(60,60,w3("poniente: fresco, umido","poniente : frais, humide","poniente: cool, humid"),"#2b7a75")+fChip(260,60,w3("levante: caldo, secco","levante : chaud, sec","levante: hot, dry"),"#b5334a"),"summer")},
 {h:I3("Il suolo albariza","Le sol d'albariza","Albariza soil"),
  c:I3("L'albariza è un suolo bianco, ricchissimo di calcare. Drena bene ma, essendo profondo e capace di trattenere molta acqua, ne immagazzina abbastanza per far superare alle viti le estati calde e secche. Per trattenere ancora più acqua, dopo la vendemmia si scavano tra i filari buche rettangolari che raccolgono la pioggia d'autunno e d'inverno, poi in primavera il terreno si livella. D'estate l'albariza forma una crosta dura che limita l'evaporazione.",
   "L'albariza est un sol blanc, très riche en calcaire. Il draine bien mais, profond et capable de retenir beaucoup d'eau, il en stocke assez pour que les vignes passent les étés chauds et secs. Pour retenir encore plus d'eau, après la vendange on creuse entre les rangs des fosses rectangulaires qui recueillent la pluie d'automne et d'hiver, puis on aplanit au printemps. L'été, l'albariza forme une croûte dure qui limite l'évaporation.",
   "Albariza is a white soil with a very high chalk content. It drains well but, being deep with excellent water-holding capacity, it stores enough water to see the vines through the hot, dry summers. To retain even more, after harvest rectangular pits are dug between the rows to trap autumn and winter rain, and the soil is smoothed out again in spring. In summer the albariza forms a hard crust that limits evaporation."),
  v:()=>fSvg(`<rect y="120" width="320" height="80" fill="#f3efe6"/>`+[40,120,200,280].map(x=>vForm("bush","canopy",x,122)).join("")+[80,160,240].map((x,i)=>fD(.6+i*.3,`<rect x="${x-14}" y="124" width="28" height="12" fill="#cfe3ee"/>`)).join("")+fChip(160,170,w3("albariza: calcare bianco","albariza : calcaire blanc","albariza: white chalk"),"#8a7d6b")+fChip(250,60,w3("buche per la pioggia","fosses pour la pluie","rain-trapping pits"),"#2b7a75"),"summer")},
 {h:I3("Le uve","Les cépages","Grape varieties"),
  c:I3("Sono permesse tre varietà. Il Palomino è la grande maggioranza: dà vini poco acidi e senza aromi varietali marcati, ideale perché lo stile nasce dall'affinamento. Il Pedro Ximénez, PX, ha anch'esso pochi aromi; la buccia sottile lo rende perfetto per l'appassimento al sole, e serve per gli Sherry dolci. Se ne coltiva pochissimo a Jerez: quasi tutto arriva dalla vicina Montilla-Moriles, cosa insolita ammessa dal disciplinare. Il Moscato d'Alessandria, in piccole quantità, serve anch'esso per vini dolci.",
   "Trois cépages sont autorisés. Le Palomino représente la grande majorité : il donne des vins peu acides et sans arômes variétaux marqués, idéal puisque le style naît de l'élevage. Le Pedro Ximénez, PX, est lui aussi peu aromatique ; sa peau fine le rend parfait pour le séchage au soleil, et il sert aux Xérès doux. On en cultive très peu à Jerez : presque tout vient de la voisine Montilla-Moriles, chose inhabituelle permise par le règlement. Le Muscat d'Alexandrie, en petites quantités, sert aussi aux vins doux.",
   "Three varieties are permitted. Palomino makes up the vast majority: it gives low-acid wines without obvious varietal aromas, ideal because the style comes from maturation. Pedro Ximénez, PX, also has little varietal flavour; its thin skin suits sun-drying, and it is used for sweet Sherries. Very little grows in Jerez: most comes from neighbouring Montilla-Moriles, an unusual feature allowed by the regulations. Muscat of Alexandria, in small amounts, is also used for sweet wines."),
  v:()=>fSvg([[60,"#d8e08a","Palomino",.9],[160,"#a8742e","Pedro Ximénez",.08],[260,"#e3cf7a","Moscatel",.02]].map(([x,c,l,f],i)=>fD(i*.4,`<g transform="translate(${x} 70)">${fBunch(0,0,2,c)}</g>`+fT(x,150,l,10)+`<rect x="${x-40}" y="160" width="${80*f+2}" height="8" fill="#d4a23a"/>`)).join(""))},
 {h:I3("Vinificazione del vino base","Vinification du vin de base","Making the base wine"),
  c:I3("Il Palomino serve per gli Sherry secchi. Con il caldo della vendemmia l'uva deve arrivare in pressa il prima possibile, per evitare l'ossidazione. Fermenta di solito in grandi vasche d'acciaio a 20–25 °C: caldo per un bianco, ma adatto a chi cerca un vino base neutro. Il risultato è un vino secco di circa 11–12 per cento.",
   "Le Palomino sert aux Xérès secs. Avec la chaleur des vendanges, le raisin doit arriver au pressoir au plus vite, pour éviter l'oxydation. Il fermente en général en grandes cuves inox à 20–25 °C : chaud pour un blanc, mais adapté à qui cherche un vin de base neutre. Le résultat est un vin sec d'environ 11 à 12 %.",
   "Palomino is used for the dry Sherries. With harvest-time heat, grapes must reach the press as fast as possible to avoid oxidation. Fermentation usually takes place in large stainless steel tanks at 20–25 °C: warm for a white, but suited to producing a neutral base wine. The result is a dry wine of about 11–12% abv."),
  v:()=>fSvg(fPress(20,60,WHITE,"#c9d26a")+fArrow("M136 90H166")+STEEL(170,40,90,124,{col:WHITE,lv:.75,bub:8})+fThermo(274,60,"20–25 °C",.55)+fChip(215,186,"11–12% vol"))},
 {h:I3("La prima classificazione","La première classification","The first classification"),
  c:I3("In autunno i vini vengono classificati: alcuni andranno all'invecchiamento biologico, altri a quello ossidativo, in base al profilo aromatico. Di solito i vini più leggeri, pallidi e fini vanno al biologico, quelli più scuri, ricchi e pesanti all'ossidativo. A questo punto il velo di lieviti, la flor, ha già iniziato a crescere su tutti i vini. Non è lasciato al caso: dipende dallo stile della casa e dai volumi necessari per i marchi. In linea di massima i vini da vigneti costieri più freschi o fermentati a temperature più basse sono più adatti al biologico; quelli dell'interno, più caldo, o fermentati più caldi, all'ossidativo.",
   "En automne les vins sont classés : certains iront au vieillissement biologique, d'autres à l'oxydatif, selon leur profil aromatique. En général les vins plus légers, pâles et fins vont au biologique, les plus foncés, riches et lourds à l'oxydatif. À ce stade le voile de levures, la flor, a déjà commencé à se développer sur tous les vins. Rien n'est laissé au hasard : cela dépend du style maison et des volumes nécessaires aux marques. En gros, les vins des vignes côtières plus fraîches ou fermentés plus frais conviennent mieux au biologique ; ceux de l'intérieur, plus chaud, ou fermentés plus chauds, à l'oxydatif.",
   "In autumn the wines are classified: some will go to biological ageing, others to oxidative ageing, based on their flavour profile. Typically lighter, paler wines with more finesse go for biological ageing, darker, richer, heavier ones for oxidative. By now the film-forming yeast, flor, has started to grow on all the wines. Nothing is left to chance: it depends on house style and the volumes the brands need. As a guide, wines from cooler coastal vineyards and/or cooler fermentations suit biological ageing; those from warmer inland sites and/or warmer fermentations suit oxidative ageing."),
  v:()=>fSvg(fFlow(SHFLOW,2,{per:4,bh:34,y0:40,gy:30}))},
 {h:I3("Fortificazione e sobretabla","Mutage et sobretabla","Fortification and sobretabla"),
  c:I3("Dopo la classificazione i vini si fortificano con un'acquavite neutra a 96 per cento e riposano qualche mese prima di entrare nella solera: è la fase di sobretabla. I vini per l'invecchiamento biologico si portano a 15–15,5 per cento, la gradazione ideale per la flor; per loro la sobretabla è decisiva, perché si aspetta di vedere se la flor si sviluppa bene, con una seconda classificazione. Quelli che non vanno bene si rifortificano per l'ossidativo o si scartano. I vini per l'ossidativo si portano al 17 per cento, gradazione a cui la flor muore.",
   "Après la classification, les vins sont mutés avec une eau-de-vie neutre à 96 % et reposent quelques mois avant d'entrer dans la solera : c'est l'étape de sobretabla. Les vins destinés au vieillissement biologique sont portés à 15–15,5 %, le degré idéal pour la flor ; pour eux la sobretabla est décisive, car on attend de voir si la flor se développe bien, avec une seconde classification. Ceux qui ne conviennent pas sont remutés pour l'oxydatif ou écartés. Les vins pour l'oxydatif sont portés à 17 %, degré auquel la flor meurt.",
   "After classification the wines are fortified with 96% neutral spirit and set aside for a few months before entering a solera system: this stage is called sobretabla. Wines for biological ageing go to 15–15.5% abv, ideal for flor; for them sobretabla is critical, as producers wait to see if the flor develops properly, with a second classification. Those that fail are refortified for oxidative ageing or rejected. Wines for oxidative ageing go to 17% abv, at which flor dies."),
  v:()=>fSvg(fBarrel(80,120,1.4,{cut:1,col:"#efe2a0",flor:1})+fBarrel(240,120,1.4,{cut:1,col:"#c9a05a"})+`<g><path d="M150 20h24v30h-24z" fill="#fbf3e2"/>${fT(162,40,"96%",8,"#8c1d40")}<animateTransform attributeName="transform" type="rotate" values="0 160 34;-30 160 34;0 160 34" dur="2.5s" repeatCount="indefinite"/></g>`+fChip(80,70,"15–15,5% · flor","#efe2a0","#2a1b20")+fChip(240,70,w3("17%: niente flor","17 % : plus de flor","17%: no flor"),"#a8642a")+fChip(160,186,"sobretabla"))},
 {h:I3("Gli Sherry dolci naturali","Les Xérès doux naturels","Naturally sweet Sherries"),
  c:I3("Le uve per i dolci naturali, soprattutto Pedro Ximénez, dopo la raccolta si fanno appassire al sole per concentrare lo zucchero; si sviluppano anche aromi di uva passa. Raggiunta la concentrazione voluta, si pressano e si avvia la fermentazione. Il mosto è così concentrato che i lieviti fanno fatica e raramente superano pochi gradi; quando la fermentazione si ferma, il vino si fortifica al 17 per cento.",
   "Les raisins des doux naturels, surtout le Pedro Ximénez, sont séchés au soleil après la cueillette pour concentrer le sucre ; des arômes de raisins secs se développent aussi. Une fois la concentration voulue atteinte, on presse et on lance la fermentation. Le moût est si concentré que les levures peinent et dépassent rarement quelques degrés ; quand la fermentation s'arrête, le vin est muté à 17 %.",
   "Grapes for naturally sweet styles, mainly Pedro Ximénez, are sun-dried after picking to concentrate their sugar, which also develops raisin flavours. Once the desired must weight is reached they are pressed and fermentation started. The juice is so concentrated that the yeast struggle and rarely manage more than a few degrees; when fermentation stops, the must is fortified to 17% abv."),
  v:()=>fSvg(fSun(270,36,16)+`<rect x="20" y="140" width="220" height="10" fill="#c79a5c"/>`+[0,1,2,3,4].map(i=>`<g transform="translate(${44+i*42} 120)">${fBunch(0,0,1.2,"#8a5a33")}<animateTransform attributeName="transform" type="scale" from="1" to=".72" dur="4s" fill="freeze" additive="sum"/></g>`).join("")+fChip(130,176,"Pedro Ximénez → 17%","#a8642a"),"summer")},
 {h:I3("Le botti e le bodegas","Les fûts et les bodegas","Butts and bodegas"),
  c:I3("Lo Sherry deve affinare in botti di rovere da 600 litri, le butts, spesso usate prima per vini non fortificati in modo da eliminare ogni aroma di legno: il rovere serve a far passare ossigeno, aiutato dal fatto che le botti sono piene solo per cinque sesti. Mantenere fresco l'ambiente a Jerez è una sfida: le bodegas tradizionali hanno muri spessi imbiancati, soffitti alti e finestre rivolte al poniente; il pavimento di terra si tiene bagnato per l'umidità. Oggi alcune sono climatizzate.",
   "Le Xérès doit s'élever en fûts de chêne de 600 litres, les butts, souvent utilisés d'abord pour des vins non mutés afin d'éliminer tout arôme boisé : le chêne sert à laisser passer l'oxygène, aidé par le fait que les fûts ne sont remplis qu'aux cinq sixièmes. Garder la fraîcheur à Jerez est un défi : les bodegas traditionnelles ont des murs épais blanchis, de hauts plafonds et des fenêtres tournées vers le poniente ; le sol en terre est maintenu humide. Certaines sont aujourd'hui climatisées.",
   "Sherry must be aged in 600-litre oak casks called butts, often first used for unfortified wine so that any oak flavour is removed: the oak lets oxygen reach the wine, helped by the butts being only five-sixths full. Keeping cool in Jerez is a challenge: traditional bodegas have thick whitewashed walls, high ceilings and windows facing the cooling poniente; the earth floors are kept damp for humidity. Some are now air-conditioned."),
  v:()=>fSvg(`<rect x="20" y="40" width="280" height="150" fill="#f6f2ea"/><path d="M10 44L160 6L310 44Z" fill="#b5634a"/>`+[60,120,200,260].map(x=>`<rect x="${x-10}" y="56" width="20" height="30" fill="#2a3a4a"/>`).join("")+[0,1,2].map(c=>[0,1].map(r=>fBarrel(80+c*80,170-r*34,.7,{cut:1,col:"#efe2a0"})).join("")).join("")+[0,1,2].map(i=>`<path d="M-20 ${64+i*8}h30" stroke="#9fd3f0" stroke-width="2"><animateTransform attributeName="transform" type="translate" from="0 0" to="60 0" dur="2s" begin="${i*.4}s" repeatCount="indefinite"/></path>`).join("")+fChip(260,22,"600 l · 5/6"))},
 {h:I3("Il sistema solera: la saca","Le système de solera : la saca","The solera system: drawing off"),
  c:I3("La solera è un sistema di gruppi di botti, i livelli, con vini di età media diversa. Il livello con i vini più vecchi si chiama solera, gli altri criaderas. Il vino da imbottigliare si preleva dalla solera, prendendone la stessa quantità da ogni botte: è la saca. La solera non si svuota mai del tutto.",
   "La solera est un système de groupes de fûts, les niveaux, contenant des vins d'âge moyen différent. Le niveau aux vins les plus vieux s'appelle la solera, les autres les criaderas. Le vin à embouteiller est tiré de la solera, en prenant la même quantité dans chaque fût : c'est la saca. La solera n'est jamais vidée complètement.",
   "The solera system is made up of groups of butts, or levels, holding wines of different average ages. The level with the oldest wine is the solera, the others are criaderas. Wine for bottling is taken from the solera, an equal amount from each butt: this is the saca. The solera is never fully emptied."),
  v:()=>fSvg(fSoleraStack(1))},
 {h:I3("Il sistema solera: il rocío","Le système de solera : le rocío","The solera system: refilling"),
  c:I3("Le botti della solera si rabboccano con la stessa quantità presa dalla prima criadera, con tre passaggi: si preleva lo stesso volume da ogni botte della prima criadera, si mescola tutto e con questo vino si rabbocca ogni botte della solera. Poi la prima criadera si rabbocca allo stesso modo dalla seconda, e così via; la criadera più giovane si rabbocca con vino di sobretabla. Le criaderas vanno da tre a quattordici. Si parla quindi solo di età media. Il vantaggio è un vino sempre uguale, perché il vino giovane prende il carattere di quello più vecchio a cui si unisce; ma non se si immette vino scadente o si preleva troppo. Le criaderas di una stessa solera si tengono spesso in edifici diversi, per non perderla tutta in un incidente.",
   "Les fûts de la solera sont complétés avec le même volume pris dans la première criadera, en trois temps : on prélève le même volume dans chaque fût de la première criadera, on mélange le tout et on complète chaque fût de la solera avec ce vin. Puis la première criadera est complétée de la même façon par la deuxième, et ainsi de suite ; la criadera la plus jeune est complétée avec du vin de sobretabla. Il y a de trois à quatorze criaderas. On ne parle donc que d'âge moyen. L'avantage est un vin toujours identique, car le vin jeune prend le caractère du plus vieux auquel il s'unit ; sauf si l'on introduit un vin médiocre ou si l'on tire trop. Les criaderas d'une même solera sont souvent dans des bâtiments différents, pour ne pas tout perdre dans un accident.",
   "The solera butts are topped up with the same volume taken from the first criadera, in three steps: an equal volume is drawn from each butt of the first criadera, it is all blended, and this wine tops up each solera butt. The first criadera is then refilled the same way from the second, and so on; the youngest criadera is topped up with sobretabla wine. There can be from three to fourteen criaderas. So only an average age can be given. The advantage is a consistent wine every time, since younger wine takes on the character of the older wine it joins; but not if poor wine is fed in or too much is drawn off. Criaderas of the same solera are often kept in different buildings so a single disaster cannot destroy it all."),
  v:()=>fSvg(fSoleraStack(2))},
 {h:I3("La flor e l'invecchiamento biologico","La flor et le vieillissement biologique","Flor and biological ageing"),
  c:I3("La flor è un insieme di ceppi di lievito che forma uno strato spesso sulla superficie del vino. Si nutre dell'alcol e di altri nutrienti del vino e dell'ossigeno dell'aria, producendo anidride carbonica e acetaldeide, che dà agli Sherry biologici il loro gusto unico. Per vivere vuole alcol, temperatura e umidità precise: non sopporta più del 15,5 per cento, ama temperature fresche o moderate e molta umidità; cresce di più in primavera e autunno e si assottiglia d'inverno e d'estate, e persino la posizione della botte nella bodega cambia il vino. Le botti scolme le danno ossigeno, e lo strato di flor protegge il vino dall'ossidazione. Poiché consuma nutrienti, serve aggiungere spesso vino nuovo, con prelievi frequenti dalla solera.",
   "La flor est un ensemble de souches de levures qui forme une couche épaisse à la surface du vin. Elle se nourrit de l'alcool et d'autres nutriments du vin et de l'oxygène de l'air, produisant du gaz carbonique et de l'acétaldéhyde, qui donne aux Xérès biologiques leur goût unique. Pour vivre elle exige alcool, température et humidité précis : pas plus de 15,5 %, des températures fraîches ou modérées et beaucoup d'humidité ; elle croît surtout au printemps et à l'automne et s'amincit l'hiver et l'été, et même la position du fût dans la bodega change le vin. Les fûts en vidange lui donnent de l'oxygène, et la couche de flor protège le vin de l'oxydation. Comme elle consomme des nutriments, il faut souvent ajouter du vin neuf, par des tirages fréquents de la solera.",
   "Flor is made up of several yeast strains that form a thick layer on the wine's surface. It feeds on the alcohol and other nutrients in the wine and on oxygen from the air, producing carbon dioxide and acetaldehyde, which gives biologically aged Sherries their unique flavour. It needs precise alcohol, temperature and humidity: no more than 15.5% abv, cool to moderate temperatures and high humidity; it grows most vigorously in spring and autumn and dies back in winter and summer, and even a butt's position in the bodega affects the wine. Part-filled butts give it oxygen, and the flor layer protects the wine from oxidation. Because it consumes nutrients, new wine must be added regularly, with frequent draws from the solera."),
  v:()=>fSvg(fBarrel(160,100,2.6,{cut:1,col:"#efe2a0",flor:1})+fCall(160,90,250,30,"flor",.4)+fD(1.2,fChip(70,30,w3("alcol + O₂ → acetaldeide","alcool + O₂ → acétaldéhyde","alcohol + O₂ → acetaldehyde"),"#d4a23a","#2a1b20"))+fChip(160,186,"≤ 15,5% · "+w3("fresco e umido","frais et humide","cool and humid")))},
 {h:I3("Quanto dura la flor","Combien de temps vit la flor","How long flor lasts"),
  c:I3("Gli Sherry biologici come il Fino perdono in fretta la freschezza e vanno bevuti il prima possibile dopo l'imbottigliamento. Si potrebbe mantenere viva la flor all'infinito, ma il vino prelevato da queste soleras raramente ha un'età media superiore a tre–quattro anni: man mano che l'età media cresce, i nutrienti nelle botti più vecchie diminuiscono, e verso i sette anni la flor comincia a cedere e compaiono note ossidative.",
   "Les Xérès biologiques comme le Fino perdent vite leur fraîcheur et se boivent au plus tôt après la mise en bouteille. On pourrait garder la flor en vie indéfiniment, mais le vin tiré de ces soleras dépasse rarement un âge moyen de trois à quatre ans : à mesure que l'âge moyen augmente, les nutriments des fûts les plus vieux diminuent, et vers sept ans la flor commence à faiblir et des notes oxydatives apparaissent.",
   "Biologically aged Sherries such as Fino quickly lose their freshness and should be drunk as soon as possible after bottling. The flor culture could be kept alive indefinitely, but wine drawn from these soleras rarely has an average age over three to four years: as the average age rises, nutrients in the oldest butts drop, and by about seven years the flor can start to fail and oxidative characters develop."),
  v:()=>fSvg(`<path d="M30 60H290" stroke="#efe2a0" stroke-width="14" stroke-linecap="round"/><path d="M200 60H290" stroke="#a8642a" stroke-width="14" stroke-linecap="round"/>`+fT(30,90,"0",9,"#fff4dc","start")+fT(120,90,w3("3–4 anni: Fino","3–4 ans : Fino","3–4 years: Fino"),9)+fT(220,90,w3("≈ 7 anni: flor cede","≈ 7 ans : la flor faiblit","≈ 7 years: flor fails"),9)+fD(1.4,fFlute(160,170,"#efe2a0",1.1)+fChip(240,150,w3("bere presto","à boire vite","drink fresh"))))},
 {h:I3("L'invecchiamento ossidativo","Le vieillissement oxydatif","Oxidative ageing"),
  c:I3("Oloroso, PX e alcuni Moscatel invecchiano in modo ossidativo, senza flor; l'Amontillado lo fa dopo un periodo biologico. L'aria nelle botti scolme accentua l'effetto dell'ossigeno; in queste soleras il vino giovane aggiunto preserva il carattere di base, che altrimenti si ossiderebbe troppo. Si può arrivare a oltre trent'anni, anche se pochi vini ci arrivano; con l'evaporazione dell'acqua l'alcol sale fino a circa il 22 per cento.",
   "L'Oloroso, le PX et certains Moscatel vieillissent de façon oxydative, sans flor ; l'Amontillado le fait après une période biologique. L'air des fûts en vidange accentue l'effet de l'oxygène ; dans ces soleras, le vin jeune ajouté préserve le caractère de base, qui sinon s'oxyderait trop. On peut dépasser trente ans, même si peu de vins y arrivent ; avec l'évaporation de l'eau, l'alcool monte jusqu'à environ 22 %.",
   "Oloroso, PX and some Muscat Sherries are aged oxidatively, without flor; Amontillado is aged oxidatively after a period of biological ageing. The air in part-filled butts greatly enhances the oxygen effect; in these soleras the young wine added preserves the base character, which would otherwise become over-oxidised. Wines can be aged for upwards of 30 years, though few get there; as water evaporates, alcohol rises to about 22% abv."),
  v:()=>fSvg(fBarrel(140,100,2.4,{cut:1,col:"#a8642a",ox:1})+fGlass(275,110,"#8a4a1a",1.1)+fChip(140,186,"17% → ≈ 22%","#a8642a"))},
 {h:I3("Gli stili secchi","Les styles secs","Dry styles"),
  c:I3("Fino e Manzanilla: solo invecchiamento biologico; giallo paglierino, agrumi, mandorla, erbe e note di pane dalla flor, gusto sapido; non migliorano in bottiglia. La Manzanilla matura a Sanlúcar, dove il clima più fresco e umido dà una flor spessa tutto l'anno e note ancora più sapide. I vini poco chiarificati e filtrati si chiamano en rama. Oloroso: solo ossidativo; bruno, corposo, mou, cuoio, spezie e noce. Amontillado: prima biologico, poi rifortificato al 17 per cento per uccidere la flor e passato in una solera ossidativa; ambrato o bruno, unisce note di lievito e ossidative. Palo Cortado: raro, con il profumo di un Amontillado e il corpo e la ricchezza di un Oloroso.",
   "Fino et Manzanilla : uniquement biologique ; jaune paille, agrumes, amande, herbes et notes de pain dues à la flor, goût salin ; ils ne s'améliorent pas en bouteille. La Manzanilla s'élève à Sanlúcar, où le climat plus frais et humide donne une flor épaisse toute l'année et des notes encore plus salines. Les vins peu collés et filtrés s'appellent en rama. Oloroso : uniquement oxydatif ; brun, corsé, caramel, cuir, épices et noix. Amontillado : d'abord biologique, puis remuté à 17 % pour tuer la flor et passé dans une solera oxydative ; ambré ou brun, il unit notes levurées et oxydatives. Palo Cortado : rare, avec le nez d'un Amontillado et le corps et la richesse d'un Oloroso.",
   "Fino and Manzanilla: biological ageing only; pale lemon, citrus, almond, herbs and bready notes from flor, a tangy, salty taste; they do not improve in bottle. Manzanilla is matured in Sanlúcar, where the cooler, more humid coast gives thick flor all year and an even tangier aroma. Minimally fined and filtered wines are labelled en rama. Oloroso: oxidative ageing only; brown, full-bodied, toffee, leather, spice and walnut. Amontillado: biological first, then refortified to 17% to kill the flor and moved into an oxidative solera; amber or brown, combining yeast-derived and oxidative notes. Palo Cortado: rare, with the aroma of an Amontillado and the body and richness of an Oloroso."),
  v:()=>fSvg([["Fino","#f1e6a6"],["Manzanilla","#efe8b8"],["Amontillado","#c9903a"],["Palo Cortado","#b0702a"],["Oloroso","#8a4a1a"]].map(([l,c],i)=>fD(i*.35,fStemGlass(34+i*63,130,"port",c)+fT(34+i*63,170,l,8.5))).join("")+fChip(160,30,w3("tutti secchi","tous secs","all dry")))},
 {h:I3("Dolci, dolcificati e con indicazione d'età","Doux, adoucis et avec indication d'âge","Sweet, sweetened and age-indicated"),
  c:I3("Dolci naturali, tutti ossidativi e rari, usati spesso per dolcificare: il PX, bruno scuro e lussureggiante, anche 500 grammi di zucchero per litro, con frutta secca, caffè e liquirizia; il Moscatel, simile ma con scorza d'agrumi. Dolcificati: il Pale Cream, con un breve periodo biologico e dolcificato di solito con mosto concentrato; il Medium, con caratteri sia biologici sia ossidativi, e il Cream, solo ossidativo, dolcificati con PX nei migliori. Oggi Amontillado, Oloroso e Palo Cortado possono essere solo secchi. Indicazioni d'età: VORS almeno 30 anni di età media e VOS almeno 20, verificati lotto per lotto; poi 12 e 15 anni, riferiti a tutta la solera. Solo Amontillado, Palo Cortado, Oloroso e PX possono averle.",
   "Doux naturels, tous oxydatifs et rares, souvent utilisés pour adoucir : le PX, brun foncé et liquoreux, jusqu'à 500 grammes de sucre par litre, aux fruits secs, café et réglisse ; le Moscatel, proche mais avec un zeste d'agrumes. Adoucis : le Pale Cream, avec une courte phase biologique et adouci en général au moût concentré ; le Medium, aux caractères biologiques et oxydatifs, et le Cream, seulement oxydatif, adoucis au PX pour les meilleurs. Aujourd'hui Amontillado, Oloroso et Palo Cortado ne peuvent être que secs. Indications d'âge : VORS au moins 30 ans d'âge moyen et VOS au moins 20, vérifiés lot par lot ; puis 12 et 15 ans, valables pour toute la solera. Seuls Amontillado, Palo Cortado, Oloroso et PX peuvent en porter.",
   "Naturally sweet, all oxidative and rare, often used to sweeten others: PX, deep brown and luscious, up to 500 g/l of sugar, with dried fruit, coffee and liquorice; Muscat, similar but with dried citrus peel. Sweetened: Pale Cream, with a short biological period and usually sweetened with RCGM; Medium, showing both biological and oxidative character, and Cream, only oxidative, the best sweetened with PX. Amontillado, Oloroso and Palo Cortado may now only be dry. Age indications: VORS at least 30 years' average age and VOS at least 20, tested batch by batch; then 12 and 15 years, applied to a whole solera. Only Amontillado, Palo Cortado, Oloroso and PX qualify."),
  v:()=>fSvg(fTable([I3("Categoria","Catégorie","Category"),I3("Età media","Âge moyen","Average age")],[["VORS","≥ 30"],["VOS","≥ 20"],[I3("15 anni","15 ans","15 years"),"15"],[I3("12 anni","12 ans","12 years"),"12"]],[0,1],{y:12,rh:24,w:180})+fStemGlass(250,80,"port","#3a1a0a")+fT(250,104,"PX ≤ 500 g/l",8.5)+fStemGlass(250,160,"port","#d9b06a")+fT(250,184,"Pale Cream",8.5))}
]},
{id:"port",sec:"s",ch:"prt",ic:"sat",t:I3("Il Porto e i Moscati fortificati","Le Porto et les Muscats mutés","Port and fortified Muscats"),s:[
 {h:I3("Il Douro e le sue sottoregioni","Le Douro et ses sous-régions","The Douro and its sub-regions"),
  c:I3("Il Porto si fa aggiungendo acquavite di vino a un mosto in fermentazione, ottenendo un vino dolce e alcolico. L'attività è divisa tra le città gemelle di Porto e Vila Nova de Gaia, alla foce del Douro, e i vigneti, che iniziano circa 70 chilometri a monte. I vigneti si dividono in tre sottoregioni: il Baixo Corgo, a ovest, più fresco e piovoso, dà i vini più leggeri; il Cima Corgo ha la maggior parte dei vigneti migliori; il Douro Superior, ancora poco piantato, più caldo e secco, è anch'esso fonte di grandi vini.",
   "Le Porto se fait en ajoutant de l'eau-de-vie de vin à un moût en fermentation, pour obtenir un vin doux et alcoolisé. L'activité se partage entre les villes jumelles de Porto et Vila Nova de Gaia, à l'embouchure du Douro, et le vignoble, qui commence à environ 70 kilomètres en amont. Il se divise en trois sous-régions : le Baixo Corgo, à l'ouest, plus frais et pluvieux, donne les vins les plus légers ; le Cima Corgo compte la plupart des meilleurs vignobles ; le Douro Superior, encore peu planté, plus chaud et sec, est aussi une source de grands vins.",
   "Port is made by adding grape spirit to fermenting juice to create a sweet, alcoholic wine. The industry is split between the twin cities of Porto and Vila Nova de Gaia, at the mouth of the Douro, and the vineyards that start about 70 kilometres upstream. The vineyards divide into three sub-regions: Baixo Corgo, in the west, coolest and wettest, gives the lightest wines; Cima Corgo has most of the top vineyards; Douro Superior, still sparsely planted, hotter and drier, is also a source of top-quality wine."),
  v:()=>fSvg(fSea(0,60,40,80)+`<path d="M40 100C90 90 120 120 170 100S260 80 320 96" stroke="#3b7fa8" stroke-width="8" fill="none"/>`+[[60,"Porto · Gaia","#5c646b"],[140,"Baixo Corgo","#4fa8a2"],[210,"Cima Corgo","#8c1d40"],[280,"Douro Superior","#d9774b"]].map(([x,l,c],i)=>fD(i*.4,`<circle cx="${x}" cy="${i?92:100}" r="7" fill="${c}"/>`+fT(x,i%2?136:70,l,9))).join("")+fArrow("M60 160H280",null,1)+fT(170,182,w3("sempre più caldo e secco","de plus en plus chaud et sec","increasingly hot and dry"),9))},
 {h:I3("Clima e scisto","Climat et schiste","Climate and schist"),
  c:I3("La zona ha un clima continentale caldo, protetta dai venti atlantici piovosi dalla Serra do Marão, ma non è uniforme: più si va a est, più fa caldo e secco. I viticoltori affrontano gelate primaverili e a volte acquazzoni che disturbano fioritura e vendemmia; d'estate di giorno fa molto caldo e piove pochissimo. La viticoltura è possibile grazie alla roccia di scisto, che si frattura in verticale e lascia arrivare le radici alle riserve d'acqua profonde accumulate dalle piogge invernali.",
   "La zone a un climat continental chaud, protégée des vents atlantiques pluvieux par la Serra do Marão, mais elle n'est pas uniforme : plus on va vers l'est, plus il fait chaud et sec. Les vignerons affrontent des gelées de printemps et parfois des averses qui perturbent floraison et vendanges ; l'été il fait très chaud le jour et il pleut très peu. La viticulture est possible grâce au schiste, qui se fracture verticalement et permet aux racines d'atteindre les réserves d'eau profondes constituées par les pluies d'hiver.",
   "The region has a warm continental climate, sheltered from rain-bearing Atlantic winds by the Serra do Marão, but it is not uniform: the further east, the hotter and drier. Growers face spring frosts and occasional downpours that disrupt flowering and harvest; summer days are very hot and growing-season rain is very low. Viticulture is possible thanks to the schist bedrock, which fractures vertically and lets roots reach deep water reserves built up by winter rains."),
  v:()=>fSvg(`<path d="M0 60Q60 20 100 60" fill="#7a8a6a"/>`+fT(50,40,"Serra do Marão",8.5)+[0,1,2].map(i=>`<path d="M-20 ${30+i*10}h40" stroke="#9fd3f0" stroke-width="2"><animateTransform attributeName="transform" type="translate" from="0 0" to="60 0" dur="1.6s" begin="${i*.3}s" repeatCount="indefinite"/></path>`).join("")+`<rect x="100" y="110" width="220" height="90" fill="#6e6a76"/>`+Array.from({length:9},(_,i)=>`<path d="M${110+i*24} 110V200" stroke="#4e4a56" stroke-width="2"/>`).join("")+vForm("bush","canopy",200,112)+`<path d="M200 112V196" stroke="#c9a27a" stroke-width="2"/>`+fD(1,`<rect x="110" y="184" width="200" height="12" fill="#4a7fa8" opacity=".6"/>`)+fChip(240,60,w3("scisto: radici profonde","schiste : racines profondes","schist: deep roots"),"#6e6a76"),"summer")},
 {h:I3("Pendii e terrazze","Pentes et terrasses","Slopes and terraces"),
  c:I3("Nel Baixo e nel Cima Corgo i vigneti stanno su pendii altissimi e ripidi lungo il Douro e i suoi affluenti; altitudine ed esposizione vengono sfruttate, anche scegliendo versanti a nord per sfuggire al sole più forte. Tradizionalmente le viti stavano su terrazze strette sostenute da muri a secco, i socalcos: poche file, nessuna meccanizzazione, muri costosi da mantenere, ma ancora molto diffuse. I patamares sono terrazze senza muri, abbastanza larghe per un trattore. Dove la pendenza è minore si usa la vinha ao alto: filari lungo la linea di pendenza, serviti da strade trasversali e verricelli; patamares e vinha ao alto soffrono però l'erosione.",
   "Dans le Baixo et le Cima Corgo, les vignes sont sur des pentes très hautes et raides le long du Douro et de ses affluents ; altitude et exposition sont exploitées, en choisissant même des versants nord pour éviter le soleil le plus fort. Traditionnellement les vignes étaient sur d'étroites terrasses soutenues par des murets, les socalcos : peu de rangs, aucune mécanisation, murs coûteux à entretenir, mais encore très répandues. Les patamares sont des terrasses sans murs, assez larges pour un tracteur. Là où la pente est plus douce on utilise la vinha ao alto : rangs dans le sens de la pente, desservis par des routes transversales et des treuils ; patamares et vinha ao alto souffrent toutefois de l'érosion.",
   "In Baixo and Cima Corgo the vineyards sit on very tall, steep slopes along the Douro and its tributaries; altitude and aspect are exploited, even choosing north-facing sites to avoid the full force of the sun. Traditionally vines were planted on narrow terraces held up by stone walls, socalcos: only a few rows each, no mechanisation and costly walls, but still widely used. Patamares are terraces without walls, wide enough for tractors. Where slopes are gentler, vinha ao alto plants rows up and down the slope, worked from cross roads with winches; patamares and vinha ao alto are, however, prone to erosion."),
  v:()=>fSvg(["socalcos","patamares","ao_alto"].map((k,i)=>`<svg x="${4+i*105}" y="34" width="102" height="140" viewBox="0 30 320 170" preserveAspectRatio="none">${fTerraces(k)}</svg>`).join("")+fChip(55,22,"socalcos")+fChip(160,22,"patamares")+fChip(265,22,"vinha ao alto")+fT(55,190,w3("muri, niente macchine","murets, pas de machines","walls, no machines"),8)+fT(160,190,w3("trattori","tracteurs","tractors"),8)+fT(265,190,w3("lungo il pendio","dans la pente","up the slope"),8))},
 {h:I3("Le uve del Porto","Les cépages du Porto","Port grape varieties"),
  c:I3("Quasi tutti i Porto rossi sono assemblaggi complessi di molte varietà, che nel Douro tendono ad avere buccia spessa, molti tannini, frutto nero e note floreali. Per i Porto di qualità se ne preferiscono cinque: Touriga Franca, Tinta Roriz, Tinta Barroca, Touriga Nacional e Tinto Cão.",
   "Presque tous les Portos rouges sont des assemblages complexes de nombreux cépages, qui dans le Douro ont tendance à avoir la peau épaisse, beaucoup de tanins, un fruit noir et des notes florales. Pour les Portos de qualité on en préfère cinq : Touriga Franca, Tinta Roriz, Tinta Barroca, Touriga Nacional et Tinto Cão.",
   "Most red Ports are complex blends of many varieties, which in the Douro tend to be thick-skinned and high in tannin, with black fruit and floral aromas. Five are preferred for premium Port: Touriga Franca, Tinta Roriz, Tinta Barroca, Touriga Nacional and Tinto Cão."),
  v:()=>fSvg(["Touriga Franca","Tinta Roriz","Tinta Barroca","Touriga Nacional","Tinto Cão"].map((l,i)=>fD(i*.35,`<g transform="translate(${36+i*62} 70)">${fBunch(0,0,1.4,["#2a0f2a","#3d1238","#4e1b44","#1f0a26","#3a1a3a"][i])}</g>`+fT(36+i*62,i%2?132:120,l,8))).join(""))},
 {h:I3("Una fermentazione brevissima","Une fermentation très courte","A very short fermentation"),
  c:I3("La fermentazione del Porto si ferma con la fortificazione quando l'alcol arriva al 5–9 per cento, per avere un vino dolce: dura quindi solo 24–36 ore. In così poco tempo le normali tecniche di estrazione dei rossi non bastano a dare il colore e i tannini attesi in un Porto: servono metodi diversi.",
   "La fermentation du Porto est arrêtée par le mutage quand l'alcool atteint 5 à 9 %, pour obtenir un vin doux : elle ne dure donc que 24 à 36 heures. En si peu de temps, les techniques d'extraction habituelles des rouges ne suffisent pas à donner la couleur et les tanins attendus d'un Porto : il faut d'autres méthodes.",
   "Port fermentation is stopped by fortification once alcohol reaches 5–9% abv, to make a sweet wine: so it only lasts about 24 to 36 hours. In so little time the usual red-wine extraction techniques are not vigorous enough to give the colour and tannin expected of Port: other methods are used."),
  v:()=>fSvg(fClock(80,80,"24–36 h")+`<rect x="150" y="70" width="140" height="16" rx="8" fill="rgba(255,255,255,.12)"/><rect x="150" y="70" width="0" height="16" rx="8" fill="#d4a23a"><animate attributeName="width" from="0" to="60" dur="2s" fill="freeze"/></rect>`+fT(220,110,w3("alcol 5–9% → stop","alcool 5–9 % → arrêt","alcohol 5–9% → stop"),10)+fD(2,fChip(220,150,w3("estrazione molto rapida","extraction très rapide","very rapid extraction"),"#b5334a")))},
 {h:I3("La pigiatura con i piedi","Le foulage aux pieds","Foot treading"),
  c:I3("È il metodo tradizionale e il riferimento con cui si confrontano tutti gli altri. Squadre di lavoratori pestano l'uva per tre–quattro ore in vasche di granito basse, i lagares. Quando la fermentazione parte, la pigiatura si ferma e si fanno regolari follature per estrarre altro colore e tannino. Oggi si usa poco perché richiede moltissima manodopera, ma resta per alcuni vini di alta gamma.",
   "C'est la méthode traditionnelle et la référence à laquelle on compare toutes les autres. Des équipes foulent le raisin pendant trois à quatre heures dans des cuves basses en granit, les lagares. Une fois la fermentation lancée, le foulage s'arrête et on pratique des pigeages réguliers pour extraire davantage de couleur et de tanins. On l'utilise peu aujourd'hui car elle demande énormément de main-d'œuvre, mais elle subsiste pour certains vins haut de gamme.",
   "This is the traditional method and the benchmark for all others. Teams of workers tread the grapes for three to four hours in shallow granite troughs called lagares. Once fermentation is under way, treading stops and the cap is punched down regularly to extract more colour and tannin. It is little used now because it is so labour-intensive, but it survives for some premium wines."),
  v:()=>fSvg(fLagar(160,170)+fChip(160,30,w3("lagar di granito · 3–4 ore","lagar en granit · 3–4 heures","granite lagar · 3–4 hours")))},
 {h:I3("Gli autovinificatori","Les autovinificateurs","Autovinifiers"),
  c:I3("Fu uno dei primi sistemi per automatizzare l'estrazione ed è ancora molto usato. L'uva pigiata va in vasche sigillate: la pressione dell'anidride carbonica della fermentazione spinge il mosto attraverso dei tubi in una vasca superiore. Quando la pressione raggiunge un certo livello, una valvola si apre e il mosto della vasca superiore, non più sostenuto dal gas, ricade sul cappello. La valvola si richiude e il ciclo ricomincia, ogni 15–20 minuti nella fase più attiva: come un rimontaggio, ma con molto più contatto. L'estrazione prima della fermentazione è limitata, e i modelli nuovi hanno pale meccaniche.",
   "Ce fut l'un des premiers systèmes pour automatiser l'extraction, et il est encore très utilisé. Le raisin foulé est placé en cuves fermées : la pression du gaz carbonique de la fermentation pousse le moût par des tuyaux dans une cuve supérieure. Quand la pression atteint un certain niveau, une soupape s'ouvre et le moût de la cuve supérieure, plus soutenu par le gaz, retombe sur le chapeau. La soupape se referme et le cycle recommence, toutes les 15 à 20 minutes en pleine activité : comme un remontage, mais avec bien plus de contact. L'extraction avant fermentation est limitée, et les modèles récents ont des pales mécaniques.",
   "One of the earliest ways to automate extraction, still widely used. Crushed grapes go into sealed vats: CO₂ pressure from the fermentation pushes the juice up pipes into a holding tank. When the pressure reaches a set level, a valve releases and the wine in the holding tank, no longer supported by the gas, floods back over the cap. The valve resets and the cycle repeats, every 15–20 minutes when fermentation is very active: like pumping over, but with far more skin contact. Pre-fermentation extraction is limited, and newer autovinifiers include mechanical paddles."),
  v:()=>fSvg(fAutovin(150,180)+fChip(250,60,w3("ciclo: 15–20 min","cycle : 15–20 min","cycle: 15–20 min"))+fChip(250,110,w3("pressione di CO₂","pression de CO₂","CO₂ pressure"),"#2b7a75"))},
 {h:I3("Pistoni e lagares robotici","Pistons et lagares robotisés","Piston plungers and robotic lagares"),
  c:I3("Questi sistemi imitano il più possibile la pigiatura con i piedi. I pistoni sono vasche d'acciaio rotonde, basse e aperte, dove il cappello viene premuto da pistoni robotizzati. Il lagar robotizzato è una vasca d'acciaio rettangolare e bassa, grande come un lagar tradizionale, con un carrello semovente dotato di «piedi» robotici che schiacciano l'uva sul fondo. Finita la fase di pigiatura, fanno follature regolari. Molti li considerano buoni quanto la pigiatura a piedi e sono molto usati per i vini di alta gamma.",
   "Ces systèmes imitent au plus près le foulage aux pieds. Les pistons sont des cuves inox rondes, basses et ouvertes, où le chapeau est enfoncé par des pistons robotisés. Le lagar robotisé est une cuve inox rectangulaire et basse, de la taille d'un lagar traditionnel, avec un portique automoteur muni de « pieds » robotiques qui écrasent le raisin contre le fond. Après la phase de foulage, ils réalisent des pigeages réguliers. Beaucoup les jugent aussi bons que le foulage aux pieds et ils sont très utilisés pour les vins haut de gamme.",
   "These systems imitate foot treading as closely as possible. Piston plungers are round, shallow, open-topped steel vats where robotic pistons press the cap down. The robotic lagar is a shallow, rectangular steel tank the size of a traditional lagar, with a self-propelled gantry carrying robotic 'feet' that squash the grapes against the floor. After the treading phase they carry out regular punch-downs. Many consider them as good as foot treading, and they are widely used for premium wines."),
  v:()=>fSvg(fRoboLagar(160,170)+fChip(160,30,w3("lagar robotizzato","lagar robotisé","robotic lagar")))},
 {h:I3("La fortificazione","Le mutage","Fortification"),
  c:I3("La fortificazione uccide i lieviti e dà un vino dolce stabile tra il 19 e il 22 per cento. Tutti i Porto sono dolci, ma non allo stesso modo: il momento della fortificazione dipende dallo zucchero iniziale e dalla dolcezza voluta da ogni casa. L'acquavite, aguardente, non può superare il 77 per cento; con un alcol basso prima della fortificazione ne servono grandi quantità: in media il 20 per cento del volume di una bottiglia di Porto è acquavite, contro circa il 3,5 per cento di un Fino.",
   "Le mutage tue les levures et donne un vin doux stable entre 19 et 22 %. Tous les Portos sont doux, mais pas au même degré : le moment du mutage dépend du sucre initial et de la douceur voulue par chaque maison. L'eau-de-vie, aguardente, ne peut dépasser 77 % ; avec un alcool bas avant le mutage, il en faut de grandes quantités : en moyenne 20 % du volume d'une bouteille de Porto est de l'eau-de-vie, contre environ 3,5 % pour un Fino.",
   "Fortification kills the yeast to create a stable sweet wine of 19–22% abv. All Port is sweet, but some is sweeter: the timing of fortification depends on the starting must weight and each house's desired sweetness. The spirit, aguardente, can be no stronger than 77% abv; with low alcohol before fortification, large volumes are needed: on average 20% of a bottle of Port is spirit, compared with about 3.5% in a Fino."),
  v:()=>fSvg(STEEL(140,40,100,124,{col:RED,lv:.75,bub:6})+`<g><path d="M60 30h36v40h-36z" fill="#fbf3e2"/>${fT(78,56,"77%",10,"#8c1d40")}<animateTransform attributeName="transform" type="rotate" values="0 78 50;40 78 50;40 78 50;0 78 50" dur="3s" repeatCount="indefinite"/></g>`+fDrops(120,70,110,"#fbf3e2",3)+fD(1.6,`<g transform="translate(272 70)">${fYeast(0,0)}<path d="M-10 -10L10 10M10 -10L-10 10" stroke="#b5334a" stroke-width="3"/></g>`)+fD(2.2,fChip(190,186,"19–22% vol · 20% "+w3("acquavite","eau-de-vie","spirit"),"#d4a23a","#2a1b20")))},
 {h:I3("Dove e come affina","Où et comment il s'élève","Where and how Port matures"),
  c:I3("Il Porto di solito scende a Vila Nova de Gaia per l'affinamento: il clima più fresco della costa è adatto a una maturazione lenta. Alcuni vini, soprattutto per i Tawny, sono sempre rimasti nel Douro, dove il caldo accelera l'invecchiamento e la perdita di colore; con i magazzini climatizzati oggi si affina di più nella zona dei vigneti. Si usano da sempre recipienti di rovere vecchio, piccoli e grandissimi, e oggi anche acciaio; gli aromi di rovere nuovo non sono mai desiderati. Il tipo di recipiente crea due grandi famiglie: gli stili ruby e gli stili tawny.",
   "Le Porto descend en général à Vila Nova de Gaia pour l'élevage : le climat plus frais de la côte convient à une maturation lente. Certains vins, surtout pour les Tawny, sont toujours restés dans le Douro, où la chaleur accélère le vieillissement et la perte de couleur ; avec les chais climatisés, on élève aujourd'hui davantage dans la zone des vignobles. On utilise depuis toujours des contenants en vieux chêne, petits et très grands, et aujourd'hui aussi l'inox ; les arômes de chêne neuf ne sont jamais recherchés. Le type de contenant crée deux grandes familles : les styles ruby et tawny.",
   "Port is usually taken downstream to Vila Nova de Gaia to mature: the cooler coastal climate suits slow maturation. Some wines, notably for Tawny, have always been stored up the Douro, where higher temperatures speed ageing and colour loss; with air-conditioned warehouses, more wine is now aged in the vineyard area. Port has always matured in old oak, small and very large, and now also stainless steel; new oak flavours are never wanted. The type of vessel creates two broad families: ruby styles and tawny styles."),
  v:()=>fSvg(`<path d="M0 120C80 110 160 140 320 120V200H0Z" fill="#3b7fa8"/>`+`<g transform="translate(70 100)"><rect x="-50" y="-40" width="100" height="40" fill="#f6f2ea"/><path d="M-54 -40L0 -60L54 -40Z" fill="#b5634a"/></g>`+fT(70,120,"Vila Nova de Gaia",9)+fSun(270,40,14)+fT(270,80,"Douro",9)+fD(1.2,`<ellipse cx="80" cy="170" rx="30" ry="22" fill="url(#fwood)"/>`+fChip(80,196,"ruby"))+fD(1.8,fBarrel(230,170,.8)+fChip(230,196,"tawny")))},
 {h:I3("Gli stili ruby","Les styles ruby","Ruby styles"),
  c:I3("Si limita l'effetto dell'ossigeno: affinamento relativamente breve in grandi botti di rovere o in acciaio, per un colore intenso e un frutto primario marcato. Il Ruby base è un assemblaggio di vini di uno–tre anni, senza la concentrazione e i tannini dei migliori. Il Reserve, o Reserva, è di qualità superiore, approvato da una commissione di degustazione. Il Late Bottled Vintage, LBV, è di una sola annata, affinato da quattro a sei anni, di solito in grandi botti, per essere più pronto del Vintage: quasi tutti sono chiarificati e filtrati e non migliorano in bottiglia, mentre i pochi non filtrati somigliano al Vintage, migliorano e fanno deposito, quindi vanno decantati.",
   "On limite l'effet de l'oxygène : élevage assez court en grands foudres de chêne ou en inox, pour une couleur intense et un fruit primaire marqué. Le Ruby de base est un assemblage de vins d'un à trois ans, sans la concentration ni les tanins des meilleurs. Le Reserve, ou Reserva, est de qualité supérieure, approuvé par une commission de dégustation. Le Late Bottled Vintage, LBV, est d'une seule année, élevé de quatre à six ans, en général en grands foudres, pour être plus accessible que le Vintage : presque tous sont collés et filtrés et ne s'améliorent pas en bouteille, tandis que les rares non filtrés ressemblent au Vintage, s'améliorent et déposent, donc se carafent.",
   "The effect of oxygen is minimised: relatively short ageing in very large oak vessels or steel tanks, for deep colour and intense primary fruit. Basic Ruby is a blend of wines one to three years old, lacking the concentration and tannin of finer styles. Reserve, or Reserva, is higher quality, approved by an official tasting panel. Late Bottled Vintage, LBV, comes from a single year and is aged four to six years, usually in large oak, to be more approachable than Vintage: most are fined and filtered and do not improve in bottle, while the few unfiltered ones resemble Vintage Port, can improve and throw a sediment, so need decanting."),
  v:()=>fSvg(fTable([I3("Stile","Style","Style"),I3("Affinamento","Élevage","Ageing")],[["Ruby",I3("1–3 anni, assemblaggio","1–3 ans, assemblage","1–3 yrs, blend")],["Reserve Ruby",I3("approvato da commissione","validé par commission","tasting panel")],["LBV",I3("1 annata, 4–6 anni","1 millésime, 4–6 ans","1 vintage, 4–6 yrs")],[I3("LBV non filtrato","LBV non filtré","Unfiltered LBV"),I3("deposito: decantare","dépôt : carafer","sediment: decant")]],[2],{y:16,rh:34}))},
 {h:I3("Vintage e Single Quinta","Vintage et Single Quinta","Vintage and Single Quinta"),
  c:I3("Il produttore deve registrare l'intenzione di fare un Vintage nel secondo anno dopo la vendemmia e imbottigliarlo entro il terzo; affina in grandi botti o acciaio e non è né chiarificato né filtrato. All'uscita è il più concentrato e tannico; si può bere giovane, ma invecchia per decenni in bottiglia formando un deposito abbondante. È di solito il vino simbolo della casa, dichiarato in media tre volte per decennio, e la scelta spetta a ogni produttore: ci fu accordo generale su 2000, 2003, 2007 e 2011. Il Single Quinta Vintage viene da una sola tenuta: i grandi produttori lo fanno con le loro migliori quinte negli anni non dichiarati, e spesso lo invecchiano in bottiglia prima di venderlo.",
   "Le producteur doit déclarer son intention de faire un Vintage la deuxième année après la vendange et le mettre en bouteille au plus tard la troisième ; il s'élève en grands foudres ou en inox et n'est ni collé ni filtré. À sa sortie c'est le plus concentré et tannique ; on peut le boire jeune, mais il vieillit des décennies en bouteille en formant un dépôt épais. C'est en général le vin phare de la maison, déclaré en moyenne trois fois par décennie, et le choix revient à chaque producteur : il y eut consensus sur 2000, 2003, 2007 et 2011. Le Single Quinta Vintage vient d'un seul domaine : les grands producteurs le font avec leurs meilleures quintas les années non déclarées, et le vieillissent souvent en bouteille avant de le vendre.",
   "Producers must register their intention to release a Vintage Port in the second year after harvest and bottle it by the third; it ages in large oak or steel and is unfined and unfiltered. On release it is the most concentrated and tannic Port; some drink it young, but it can age for decades in bottle, throwing a heavy sediment. It is usually the house's flagship, declared on average three times a decade, and each producer decides: there was general agreement on 2000, 2003, 2007 and 2011. Single Quinta Vintage Port comes from one estate: large producers make it from their best quintas in undeclared years, often ageing it in bottle before release."),
  v:()=>fSvg(fBottle(80,120,{col:"#2a0812",cork:1,label:1,lees:1})+fD(.8,fDecanter(170,170,"#5a0f24"))+fD(1.4,fBox(214,30,96,70,w3("dichiarato ≈ 3 volte per decennio","déclaré ≈ 3 fois par décennie","declared ≈ 3 times a decade"),{fill:"rgba(140,29,64,.6)"}))+fChip(80,186,"2000 · 2003 · 2007 · 2011"))},
 {h:I3("Gli stili tawny","Les styles tawny","Tawny styles"),
  c:I3("I veri Tawny si fanno come i ruby, ma invecchiano a lungo in modo ossidativo in botti chiamate pipes. Il colore passa al granato e poi al tawny, aranciato; solo i più vecchi diventano del tutto bruni. Il frutto primario sfuma verso l'uva passa, con noce, caffè, cioccolato e caramello. Il deposito si forma in botte, sono pronti all'uscita e non migliorano in bottiglia. Il Tawny economico ha il colore bruno senza un lungo invecchiamento: si usano vini più leggeri del Baixo Corgo, Porto bianco, un periodo al caldo nel Douro o un forte collaggio. Il Reserve Tawny deve affinare almeno sei anni in legno. I Tawny con indicazione d'età, 10, 20, 30 o 40 anni, indicano un'età media e devono riportare l'anno d'imbottigliamento, perché perdono freschezza in bottiglia.",
   "Les vrais Tawny se font comme les ruby, mais vieillissent longtemps de façon oxydative dans des fûts appelés pipes. La couleur passe au grenat puis au tawny, orangé ; seuls les plus vieux deviennent complètement bruns. Le fruit primaire évolue vers le raisin sec, avec noix, café, chocolat et caramel. Le dépôt se forme en fût, ils sont prêts à la sortie et ne s'améliorent pas en bouteille. Le Tawny bon marché a la couleur brune sans long vieillissement : on utilise des vins plus légers du Baixo Corgo, du Porto blanc, un passage au chaud dans le Douro ou un fort collage. Le Reserve Tawny doit vieillir au moins six ans en bois. Les Tawny avec indication d'âge, 10, 20, 30 ou 40 ans, indiquent un âge moyen et doivent porter l'année de mise en bouteille, car ils perdent leur fraîcheur en bouteille.",
   "True Tawny Ports are made like ruby styles but undergo long oxidative ageing in casks called pipes. The colour turns garnet and then tawny; only the very oldest become fully brown. Primary fruit fades to raisin, with walnut, coffee, chocolate and caramel. The deposit forms in wood, they are ready on release and do not improve in bottle. Inexpensive Tawny gets its colour without long ageing: lighter wines from Baixo Corgo, white Port, hot maturation in the Douro or heavy fining. Reserve Tawny must spend at least six years in wood. Tawny with an indication of age, 10, 20, 30 or 40 years, states an average age and must show the bottling year, because these wines lose freshness after bottling."),
  v:()=>fSvg([0,1,2].map(i=>fBarrel(60+i*80,90,.9,{cut:1,col:mixC("#8a2a20","#b0702a",i/2),ox:1})).join("")+[["10","#9a3a24"],["20","#a85428"],["30","#b06a2c"],["40","#b8803a"]].map(([n,c],i)=>fD(.8+i*.3,fStemGlass(60+i*66,170,"port",c)+fT(60+i*66,196,n+w3(" anni"," ans"," yrs"),8.5))).join("")+fChip(160,26,"Reserve Tawny ≥ 6 "+w3("anni","ans","yrs")))},
 {h:I3("I Moscati fortificati","Les Muscats mutés","Fortified Muscats"),
  c:I3("Il Moscato si fortifica in tutto il mondo: le varietà che si chiamano così hanno acidità medio-bassa e profumi di fiori d'arancio, rosa e uva; prosperano nei climi caldi, ma i vigneti migliori hanno qualche influenza rinfrescante. Due stili. Giovani e non invecchiati, come il Muscat de Beaumes-de-Venise del Rodano meridionale: uve mature e sane, senza appassimento, un po' di contatto con le bucce per più aroma, fermentazione fresca fermata con acquavite al 96 per cento, conservazione in recipienti inerti senza ossigeno; dorati, floreali, dolci ma raramente lussureggianti. Invecchiati, come il Rutherglen australiano: a volte un leggero appassimento in pianta, fermentazione sulle bucce, per lo stile più ricco fortificazione già al 2 per cento, poi decenni di invecchiamento ossidativo in grandi botti vecchie, a volte al caldo; da ambrati a bruni, e i più vecchi si rinfrescano con un po' di vino giovane.",
   "Le Muscat est muté dans le monde entier : les cépages qui portent ce nom ont une acidité faible à moyenne et des arômes de fleur d'oranger, rose et raisin ; ils prospèrent en climat chaud, mais les meilleures vignes ont une influence rafraîchissante. Deux styles. Jeunes et non vieillis, comme le Muscat de Beaumes-de-Venise du Rhône méridional : raisins mûrs et sains, sans passerillage, un peu de macération pelliculaire pour plus d'arômes, fermentation fraîche arrêtée à l'eau-de-vie à 96 %, conservation en contenant inerte sans oxygène ; dorés, floraux, doux mais rarement liquoreux. Vieillis, comme le Rutherglen australien : parfois un léger passerillage sur souche, fermentation sur peaux, pour le style le plus riche mutage dès 2 %, puis des décennies de vieillissement oxydatif en grands vieux foudres, parfois au chaud ; de l'ambré au brun, et les plus vieux sont rafraîchis avec un peu de vin jeune.",
   "Muscat is fortified all over the world: the varieties called Muscat have low to medium acidity and aromas of orange blossom, rose and grape; they thrive in warm climates, but the best vineyards have some cooling influence. Two styles. Youthful and unaged, like Muscat de Beaumes-de-Venise from the Southern Rhône: ripe, healthy grapes with no drying, some skin contact for aroma, a cool fermentation stopped with 96% spirit, storage in inert vessels away from oxygen; medium gold, floral, sweet but rarely luscious. Aged, like Australia's Rutherglen Muscat: perhaps some raisining on the vine, fermentation on the skins, for the most luscious style fortification as early as 2% abv, then decades of oxidative ageing in large old oak, sometimes warm; amber to brown, the oldest refreshed with a little younger wine."),
  v:()=>fSvg(fBox(16,24,140,40,"Beaumes-de-Venise",{fill:"rgba(233,220,140,.35)"})+fBox(166,24,140,40,"Rutherglen",{fill:"rgba(138,74,26,.6)"})+fStemGlass(86,140,"port","#e8c860")+fStemGlass(236,140,"port","#7a3a14")+fT(86,180,w3("giovane, floreale, inerte","jeune, floral, inerte","young, floral, inert"),9)+fT(236,180,w3("ossidativo, decenni","oxydatif, décennies","oxidative, decades"),9))}
]},
{id:"serve",sec:"t",ch:"srv",ic:"tf",t:I3("Conservazione e servizio del vino","Conservation et service du vin","Storage and service of wine"),s:[
 {h:I3("Conservare il vino","Conserver le vin","Storing wine"),
  c:I3("Un vino conservato male cambia gusto e, nei casi gravi, diventa difettoso. Per la conservazione lunga la temperatura deve essere fresca e costante, tra 10 e 15 °C: la cucina è uno dei posti peggiori. Mesi in frigorifero induriscono i tappi, che non sigillano più, e gli spumanti perdono le bollicine. Le bottiglie con il sughero si tengono coricate perché il tappo resti bagnato; con il tappo a vite si possono tenere in piedi. Lontano dalla luce, naturale o artificiale, che scalda e invecchia il vino e può dare odori sgradevoli, e lontano dalle vibrazioni.",
   "Un vin mal conservé change de goût et, dans les cas graves, devient défectueux. Pour une longue garde, la température doit être fraîche et constante, entre 10 et 15 °C : la cuisine est l'un des pires endroits. Des mois au réfrigérateur durcissent les bouchons, qui ne sont plus étanches, et les effervescents perdent leurs bulles. Les bouteilles bouchées au liège se gardent couchées pour que le bouchon reste humide ; avec une capsule à vis, on peut les garder debout. Loin de la lumière, naturelle ou artificielle, qui chauffe et vieillit le vin et peut donner des odeurs désagréables, et loin des vibrations.",
   "Incorrectly stored wine changes flavour and, in severe cases, becomes faulty. For long-term storage the temperature should be cool and constant, 10–15 °C: the kitchen is one of the worst places. Months in a fridge harden corks so the seal fails, and sparkling wines lose their fizz. Bottles with corks are stored on their side so the cork stays moist; screw-capped bottles can stand upright. Keep wine away from light, natural or artificial, which heats and ages it and can cause unpleasant flavours, and away from vibration."),
  v:()=>fSvg([0,1,2].map(r=>[0,1,2,3].map(c=>`<g transform="translate(${40+c*46} ${60+r*40}) rotate(90)">${fBottle(0,0,{col:RED,cork:1})}</g>`).join("")).join("")+fBottle(250,130,{col:WHITE,label:1})+`<rect x="243" y="80" width="14" height="10" fill="#c9ced3"/>`+fThermo(290,40,"10–15 °C",.35,"#4fa8a2"))},
 {h:I3("Le temperature di servizio","Les températures de service","Serving temperatures"),
  c:I3("Bianchi medio-pieni e affinati in legno, come un Borgogna bianco o un Fumé Blanc: leggermente freschi, 10–13 °C. Bianchi leggeri o di medio corpo, come Muscadet, Pinot Grigio, Sauvignon neozelandese e Fino: freddi, 7–10 °C. Vini dolci, come Sauternes ed Eiswein: ben freddi, 6–8 °C. Spumanti, come Champagne, Cava e Asti: ben freddi, 6–10 °C. Rossi leggeri, come Beaujolais e Valpolicella: leggermente freschi, intorno ai 13 °C. Rossi di medio o pieno corpo, come Bordeaux, Rioja, Shiraz australiano, Châteauneuf-du-Pape, Barolo, Amarone e Vintage Port: a temperatura ambiente, 15–18 °C.",
   "Blancs moyennement corsés à corsés et boisés, comme un Bourgogne blanc ou un Fumé Blanc : légèrement frais, 10–13 °C. Blancs légers ou moyens, comme Muscadet, Pinot Grigio, Sauvignon néo-zélandais et Fino : frais, 7–10 °C. Vins doux, comme Sauternes et Eiswein : bien frais, 6–8 °C. Effervescents, comme Champagne, Cava et Asti : bien frais, 6–10 °C. Rouges légers, comme Beaujolais et Valpolicella : légèrement frais, autour de 13 °C. Rouges moyennement corsés à corsés, comme Bordeaux, Rioja, Shiraz australienne, Châteauneuf-du-Pape, Barolo, Amarone et Vintage Port : à température ambiante, 15–18 °C.",
   "Medium to full-bodied oaked whites, such as white Burgundy or Fumé Blanc: lightly chilled, 10–13 °C. Light to medium-bodied whites, such as Muscadet, Pinot Grigio, New Zealand Sauvignon and Fino: chilled, 7–10 °C. Sweet wines, such as Sauternes and Eiswein: well chilled, 6–8 °C. Sparkling wines, such as Champagne, Cava and Asti: well chilled, 6–10 °C. Light-bodied reds, such as Beaujolais and Valpolicella: lightly chilled, about 13 °C. Medium to full-bodied reds, such as Bordeaux, Rioja, Australian Shiraz, Châteauneuf-du-Pape, Barolo, Amarone and Vintage Port: room temperature, 15–18 °C."),
  v:()=>fSvg(fTable([I3("Stile","Style","Style"),"°C"],[[I3("Spumanti","Effervescents","Sparkling"),"6–10"],[I3("Dolci","Liquoreux","Sweet"),"6–8"],[I3("Bianchi leggeri, Fino","Blancs légers, Fino","Light whites, Fino"),"7–10"],[I3("Bianchi pieni, in legno","Blancs corsés, boisés","Full oaked whites"),"10–13"],[I3("Rossi leggeri","Rouges légers","Light reds"),"≈ 13"],[I3("Rossi medi e pieni","Rouges moyens à corsés","Medium–full reds"),"15–18"]],[],{y:10,rh:28}))},
 {h:I3("Raffreddare e riscaldare","Rafraîchir et réchauffer","Chilling and warming"),
  c:I3("Con aria condizionata e riscaldamento, la «temperatura ambiente» può essere troppo calda o troppo fredda. Un rosso troppo freddo sembra magro e duro: lo si lascia scaldare piano o si tiene il bicchiere tra le mani, mai sul termosifone, che lo rovinerebbe. Sopra i 18 °C perde freschezza e gli aromi si confondono; raffreddato, ritrova l'equilibrio. Per tenere freschi bianchi, rosati e spumanti si usa il secchiello, pieno per tre quarti di acqua e ghiaccio in parti uguali: l'acqua circonda la bottiglia e trasferisce il calore, mentre il solo ghiaccio, isolato dall'aria, raffredda lentamente. Troppo freddo però copre gli aromi.",
   "Avec la climatisation et le chauffage, la « température ambiante » peut être trop chaude ou trop froide. Un rouge trop froid paraît maigre et dur : on le laisse se réchauffer doucement ou on tient le verre dans les mains, jamais sur un radiateur, qui l'abîmerait. Au-delà de 18 °C il perd sa fraîcheur et les arômes se brouillent ; rafraîchi, il retrouve son équilibre. Pour garder frais blancs, rosés et effervescents, on utilise le seau, rempli aux trois quarts d'eau et de glace à parts égales : l'eau entoure la bouteille et transfère la chaleur, alors que la glace seule, isolée par l'air, refroidit lentement. Trop de froid masque toutefois les arômes.",
   "With air-conditioning and central heating, 'room temperature' can be too hot or too cold. A red that is too cold tastes thin and harsh: let it warm slowly or hold the glass in your hands, never on a radiator, which can ruin it. Above 18 °C it loses freshness and the flavours become muddled; cooled down, it regains balance. To keep whites, rosés and sparkling wines cold, use an ice bucket three-quarters full of equal parts ice and water: the water surrounds the bottle and carries the heat away, while ice alone, insulated by air, chills slowly. Over-chilling, though, masks flavour."),
  v:()=>fSvg(fBucket(80,170)+fBottle(80,110,{col:WHITE,cork:1})+fT(80,190,w3("acqua + ghiaccio","eau + glace","water + ice"),9)+fStemGlass(220,150,"red","#7a1530")+`<path d="M196 150q-10 -10 0 -20M244 150q10 -10 0 -20" stroke="#e7c3a3" stroke-width="6" fill="none"/>`+fD(1.4,fChip(220,40,w3("mai sul termosifone","jamais sur un radiateur","never on a radiator"),"#b5334a")))},
 {h:I3("I bicchieri","Les verres","Glassware"),
  c:I3("Il bicchiere giusto migliora l'esperienza. Rossi: bicchieri grandi, per mettere a contatto con l'aria una superficie ampia e sviluppare gli aromi. Bianchi e rosati: bicchieri medi, che raccolgono le note fresche e fruttate verso l'alto. Spumanti: flûte, dove le bollicine attraversano più vino prima di scoppiare; le vecchie coppe sono inadatte, perché le bollicine si perdono subito. Fortificati: bicchieri piccoli per l'alcol alto, ma abbastanza grandi da far ruotare il vino e annusarlo. I bicchieri devono essere pulitissimi: residui di detersivo o sale danno odori strani e fanno perdere le bollicine; meglio lucidarli prima con un panno di lino.",
   "Le bon verre améliore la dégustation. Rouges : grands verres, pour mettre une large surface au contact de l'air et développer les arômes. Blancs et rosés : verres moyens, qui concentrent les notes fraîches et fruitées vers le haut. Effervescents : flûtes, où les bulles traversent plus de vin avant d'éclater ; les anciennes coupes ne conviennent pas, car les bulles se perdent vite. Vins mutés : petits verres à cause de l'alcool, mais assez grands pour faire tourner le vin et le sentir. Les verres doivent être impeccables : des résidus de détergent ou de sel donnent des odeurs étranges et font perdre les bulles ; mieux vaut les polir avant avec un torchon de lin.",
   "The right glass enhances the experience. Reds: larger glasses, so a wide surface meets the air and aromas develop. Whites and rosés: medium-sized glasses that gather fresh, fruity aromas towards the top. Sparkling: flutes, where bubbles travel through more wine before bursting; old saucer-shaped coupes are unsuitable as bubbles are quickly lost. Fortified wines: small glasses for the high alcohol, but large enough to swirl and nose. Glasses must be spotless: detergent or salt residues give strange smells and kill the sparkle; it is best to polish them with a linen cloth before use."),
  v:()=>fSvg([["flute","#efe3a0",w3("spumante","effervescent","sparkling")],["port","#5a0f24","Porto"],["white","#e9dc8c",w3("bianco","blanc","white")],["red","#7a1530",w3("rosso","rouge","red")],["coupe","#efe3a0","✗"]].map(([k,c,l],i)=>fD(i*.3,fStemGlass(36+i*62,140,k,c)+fT(36+i*62,178,l,9,i===4?"#b5334a":"#fff4dc"))).join(""))},
 {h:I3("Aprire una bottiglia di vino fermo","Ouvrir une bouteille de vin tranquille","Opening a bottle of still wine"),
  c:I3("Si taglia la capsula sotto il bordo della bottiglia, con un tagliacapsule o un coltello. Si pulisce il collo con un panno. Si estrae il tappo con il cavatappi, il più delicatamente e pulitamente possibile. Si pulisce di nuovo il collo, dentro e fuori, e si versa un assaggio nel bicchiere per controllare che il vino sia in buono stato.",
   "On coupe la capsule sous la bague de la bouteille, avec un coupe-capsule ou un couteau. On essuie le col avec un linge. On retire le bouchon avec le tire-bouchon, le plus doucement et proprement possible. On nettoie à nouveau le col, dedans et dehors, et on verse un peu de vin dans un verre pour vérifier son état.",
   "Remove the top of the capsule by cutting below the lip of the bottle with a foil cutter or knife. Wipe the neck with a clean cloth. Draw the cork as gently and cleanly as possible with your chosen corkscrew. Give the neck a final clean inside and out, and pour a sample to check the wine's condition."),
  v:()=>fSvg(fBottle(110,130,{col:RED,cork:1,label:1})+`<g><animateTransform attributeName="transform" type="translate" values="0 0;0 0;0 -30;0 -30" keyTimes="0;.4;.8;1" dur="4s" repeatCount="indefinite"/><path d="M110 54V30M98 30H122" stroke="#c9ced3" stroke-width="3"/><path d="M110 54q4 3 0 6q-4 3 0 6" stroke="#c9ced3" stroke-width="2" fill="none"/></g>`+[[I3("1 capsula","1 capsule","1 capsule"),40],[I3("2 pulire","2 essuyer","2 wipe"),76],[I3("3 stappare","3 déboucher","3 draw cork"),112],[I3("4 assaggio","4 goûter","4 sample"),148]].map(([l,y],i)=>fD(i*.6,fChip(240,y,tx(l)))).join(""))},
 {h:I3("Decantare","Carafer","Decanting"),
  c:I3("I vini con un deposito abbondante vanno decantati: è un deposito naturale, che si forma invecchiando in molti buoni rossi. Alcuni vini giovani beneficiano dell'aerazione, ma basta anche farli ruotare nel bicchiere; stappare la bottiglia in anticipo invece non serve a nulla, perché il vino a contatto con l'aria è troppo poco. Si toglie la bottiglia coricata dalla rastrelliera e la si mette in un cestello, senza smuovere il deposito; si toglie piano la capsula, si pulisce e si stappa con delicatezza. Poi, davanti a una luce, si versa lentamente nel decanter finché il deposito non arriva al collo: lì ci si ferma.",
   "Les vins avec un dépôt important doivent être carafés : c'est un dépôt naturel, qui se forme en vieillissant dans de nombreux bons rouges. Certains vins jeunes profitent de l'aération, mais il suffit aussi de les faire tourner dans le verre ; ouvrir la bouteille à l'avance ne sert à rien, car trop peu de vin est au contact de l'air. On sort la bouteille couchée du casier et on la place dans un panier, sans remuer le dépôt ; on retire doucement la capsule, on nettoie et on débouche délicatement. Puis, devant une lumière, on verse lentement dans la carafe jusqu'à ce que le dépôt arrive au col : on s'arrête là.",
   "Wines with a heavy deposit need decanting: the deposit is natural and forms as many good red wines age. Some young wines benefit from aeration, though swirling in the glass works just as well; opening a bottle early does no good, as too little wine meets the air. Take the bottle from its rack horizontally and place it in a decanting basket, without disturbing the deposit; gently remove the capsule, clean the neck and draw the cork. Then, holding the bottle in front of a light, pour slowly into the decanter until the deposit reaches the neck: stop there."),
  v:()=>fSvg(fCandle(150,170)+`<g transform="translate(120 70) rotate(110)">${fBottle(0,0,{col:"#4a0d22",lees:1})}</g>`+fDecanter(220,170,"#5a0f24")+`<path d="M172 96Q200 110 214 130" stroke="#5a0f24" stroke-width="3" fill="none"/>`+fChip(160,26,w3("fermarsi quando il deposito arriva al collo","s'arrêter quand le dépôt arrive au col","stop when the deposit reaches the neck")))},
 {h:I3("Aprire uno spumante","Ouvrir un effervescent","Opening sparkling wine"),
  c:I3("In una bottiglia di spumante c'è molta pressione; raffreddarla bene la riduce, ma il tappo può comunque saltare con violenza e ferire. Si toglie la stagnola e si allenta la gabbietta, tenendo da quel momento il tappo ben fermo. Si inclina la bottiglia di circa 30 gradi, tenendo il tappo con una mano e la base con l'altra. Si gira la bottiglia, non il tappo, e si accompagna il tappo trattenendolo. Il gas deve uscire con un leggero sospiro, non con un'esplosione e un tappo che vola.",
   "Une bouteille d'effervescent est sous forte pression ; bien la rafraîchir la réduit, mais le bouchon peut quand même partir violemment et blesser. On retire la feuille et on desserre le muselet, en tenant dès lors fermement le bouchon. On incline la bouteille d'environ 30 degrés, le bouchon dans une main et la base dans l'autre. On tourne la bouteille, pas le bouchon, et on accompagne le bouchon en le retenant. Le gaz doit s'échapper avec un léger soupir, pas avec une explosion et un bouchon qui vole.",
   "There is considerable pressure in a bottle of sparkling wine; chilling helps reduce it, but the cork can still fly out violently and injure someone. Remove the foil and loosen the wire cage, holding the cork securely from that moment. Tilt the bottle at about 30 degrees, gripping the cork with one hand and the base with the other. Turn the bottle, not the cork, and ease the cork out, resisting its push. The gas should be released with a quiet sigh, not an explosion and a flying cork."),
  v:()=>fSvg(`<g transform="translate(160 120) rotate(-60)">${fBottle(0,0,{col:WHITE,cork:1})}</g>`+`<path d="M70 150A90 90 0 0 1 90 100" stroke="#d4a23a" stroke-width="2" fill="none"/>`+fT(60,140,"30°",12,"#f3cd8a")+`<g><animateTransform attributeName="transform" type="rotate" values="0 160 120;-40 160 120;0 160 120" dur="3s" repeatCount="indefinite"/><path d="M200 160a14 14 0 1 1 10 -12" stroke="#fff4dc" stroke-width="2" fill="none" marker-end="url(#fah)"/></g>`+fChip(240,40,w3("gira la bottiglia, non il tappo","tourner la bouteille, pas le bouchon","turn the bottle, not the cork")))},
 {h:I3("Quanti bicchieri e come conservare dopo l'apertura","Combien de verres et conserver après ouverture","Measures and keeping opened wine"),
  c:I3("Da una bottiglia standard da 75 cl si ottengono sei bicchieri da 125 ml, quattro da 175 ml o tre da 250 ml: utile per calcolare quante bottiglie ordinare. Un vino aperto perde intensità aromatica in pochi giorni e poi si ossida e prende odore di aceto. Il modo più semplice per allungargli la vita è richiuderlo e metterlo in frigo, ma si guadagnano solo pochi giorni. Per tempi più lunghi esistono i sistemi sottovuoto, che tolgono l'ossigeno, non adatti agli spumanti, e i sistemi a gas, che coprono il vino con un gas più pesante dell'ossigeno.",
   "Une bouteille standard de 75 cl donne six verres de 125 ml, quatre de 175 ml ou trois de 250 ml : utile pour calculer combien de bouteilles commander. Un vin ouvert perd son intensité aromatique en quelques jours, puis s'oxyde et prend une odeur de vinaigre. La façon la plus simple de prolonger sa vie est de le reboucher et de le mettre au réfrigérateur, mais on ne gagne que quelques jours. Pour plus longtemps, il existe les systèmes sous vide, qui retirent l'oxygène, inadaptés aux effervescents, et les systèmes à gaz, qui recouvrent le vin d'un gaz plus lourd que l'oxygène.",
   "A standard 75 cl bottle gives six 125 ml glasses, four 175 ml or three 250 ml: useful for working out how many bottles to order. Opened wine loses aromatic intensity within days and then oxidises and smells of vinegar. The simplest way to extend its life is to reseal it and put it in the fridge, but this gains only a few days. For longer, there are vacuum systems that remove the oxygen, unsuitable for sparkling wine, and blanket systems that cover the wine with a gas heavier than oxygen."),
  v:()=>fSvg([["6 × 125 ml",6],["4 × 175 ml",4],["3 × 250 ml",3]].map(([l,n],r)=>fT(60,40+r*36,l,10,"#f3cd8a","start")+Array.from({length:n},(_,i)=>fD(r*.4+i*.1,`<rect x="${150+i*22}" y="${26+r*36}" width="14" height="${8+(6-n)*4}" rx="2" fill="#7a1530"/>`)).join("")).join("")+fD(1.6,fBottle(90,170,{col:RED})+`<rect x="80" y="122" width="20" height="10" rx="3" fill="#5c646b"/>`+fChip(180,160,w3("sottovuoto · gas inerte","sous vide · gaz neutre","vacuum · gas blanket"))))}
]}
);
